// Made by scripts/embed-dashboard.mjs from server/dashboard/index.html. Edit that file, not this one.
const HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex\">\n<title>Board Battles · Control room</title>\n<style>\n:root{--bg:#120c08;--panel:#1c130d;--panel2:#241810;--line:#3a2a1e;--gold:#f3cd62;--gold2:#c9a25a;--text:#f4e6c8;--muted:#b9a88a;--ok:#4fae6a;--bad:#d4574a;--warn:#e0a03a;--ink:#1b120c}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 system-ui,-apple-system,\"Segoe UI\",Tahoma,sans-serif}\na{color:var(--gold)}\nbutton,input,select,textarea{font:inherit;color:inherit}\n.app{display:grid;grid-template-columns:220px 1fr;min-height:100vh}\nnav.side{background:#0d0805;border-right:1px solid var(--line);padding:16px 10px;position:sticky;top:0;height:100vh;overflow:auto}\n.brand{display:block;padding:4px 10px 16px;color:var(--gold);font-weight:800;font-size:16px}\n.brand small{display:block;color:var(--muted);font-weight:500;font-size:11px}\nnav.side a{display:flex;justify-content:space-between;align-items:center;padding:7px 12px;border-radius:9px;color:var(--text);text-decoration:none;margin-bottom:2px}\nnav.side a:hover{background:var(--panel)}\nnav.side a.on{background:var(--gold);color:var(--ink);font-weight:700}\n.pill{background:var(--bad);color:#fff;border-radius:99px;font-size:11px;padding:0 7px;font-weight:700}\nnav.side a.on .pill{background:var(--ink);color:var(--gold)}\nmain{padding:22px 26px 60px;min-width:0}\nh1{font-size:22px;margin:0 0 4px;color:var(--gold)}\nh2{font-size:16px;margin:22px 0 10px;color:var(--gold)}\n.sub{color:var(--muted);font-size:13px}\n.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}\n.grid{display:grid;gap:12px;grid-template-columns:repeat(auto-fill,minmax(180px,1fr))}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px}\n.kpi .v{font-size:24px;font-weight:800;color:#fff;letter-spacing:.2px}\n.kpi .l{color:var(--muted);font-size:12px}\n.kpi.alert{border-color:var(--warn)}\n.flags{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}\n.flag{padding:4px 10px;border-radius:99px;font-size:12px;font-weight:700;background:var(--panel2);border:1px solid var(--line)}\n.flag.on{background:rgba(79,174,106,.15);border-color:var(--ok);color:#9fe0b0}\n.flag.off{color:var(--muted)}\n.flag.warn{background:rgba(224,160,58,.15);border-color:var(--warn);color:#ffd08a}\ntable{width:100%;border-collapse:collapse;background:var(--panel);border:1px solid var(--line);border-radius:12px;overflow:hidden}\nth,td{padding:9px 10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}\nth{color:var(--gold);font-weight:600;font-size:12px;text-transform:uppercase;letter-spacing:.4px;background:var(--panel2)}\ntr:last-child td{border-bottom:0}\ntr.click{cursor:pointer} tr.click:hover td{background:var(--panel2)}\ntd.num,th.num{text-align:right;font-variant-numeric:tabular-nums}\n.tablewrap{overflow-x:auto}\n.btn{text-decoration:none;color:var(--text);border:1px solid var(--line);background:var(--panel2);border-radius:9px;padding:7px 12px;cursor:pointer;font-weight:600}\n.btn:hover{border-color:var(--gold2)}\n.btn.gold{background:var(--gold);color:var(--ink);border-color:var(--gold)}\n.btn.ok{background:var(--ok);border-color:var(--ok);color:#fff}\n.btn.bad{background:var(--bad);border-color:var(--bad);color:#fff}\n.btn.sm{padding:4px 9px;font-size:12px}\n.btn:disabled{opacity:.5;cursor:default}\ninput,select,textarea{background:#0d0805;border:1px solid var(--line);border-radius:9px;padding:7px 10px}\ninput:focus,select:focus,textarea:focus{outline:2px solid var(--gold2);outline-offset:-1px}\ninput[type=number]{width:150px}\ntd:first-child,td:nth-child(2){white-space:nowrap}\nlabel.f{display:grid;gap:4px;font-size:12px;color:var(--muted)}\nlabel.f input,label.f select,label.f textarea{color:var(--text);font-size:14px;width:100%;min-width:0}\nlabel.f input[type=color]{width:52px}\n.form{display:grid;gap:12px;grid-template-columns:repeat(auto-fill,minmax(200px,1fr))}\n.switch{display:inline-flex;align-items:center;gap:8px;cursor:pointer;user-select:none}\n.switch input{width:38px;height:22px;appearance:none;background:var(--line);border-radius:99px;position:relative;cursor:pointer;padding:0;border:0}\n.switch input::after{content:\"\";position:absolute;top:3px;left:3px;width:16px;height:16px;border-radius:50%;background:#fff;transition:.15s}\n.switch input:checked{background:var(--ok)}\n.switch input:checked::after{left:19px}\n.tabs{display:flex;gap:6px;margin:10px 0 14px;flex-wrap:wrap}\n.tabs button{border:1px solid var(--line);background:var(--panel);border-radius:99px;padding:5px 14px;cursor:pointer}\n.tabs button.on{background:var(--gold);color:var(--ink);border-color:var(--gold);font-weight:700}\n.chart{display:block;width:100%;height:auto}\n.toast{position:fixed;bottom:18px;left:50%;transform:translateX(-50%);background:var(--gold);color:var(--ink);padding:10px 18px;border-radius:10px;font-weight:700;box-shadow:0 10px 30px rgba(0,0,0,.5);z-index:50}\n.toast.err{background:var(--bad);color:#fff}\n.drawer{position:fixed;inset:0 0 0 auto;width:min(720px,100%);background:var(--bg);border-left:1px solid var(--line);overflow:auto;padding:20px 22px;z-index:40;box-shadow:-20px 0 40px rgba(0,0,0,.5)}\n.shade{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:30}\n.x{float:right}\n.muted{color:var(--muted)}\n.tag{display:inline-block;padding:1px 8px;border-radius:99px;font-size:11px;font-weight:700;background:var(--panel2);border:1px solid var(--line)}\n.tag.paid,.tag.on,.tag.google,.tag.apple{color:#9fe0b0;border-color:var(--ok)}\n.tag.pending{color:#ffd08a;border-color:var(--warn)}\n.tag.rejected,.tag.banned{color:#ff9d92;border-color:var(--bad)}\n.mono{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px}\n.bracket{display:flex;gap:18px;overflow-x:auto;padding-bottom:6px}\n.round{display:grid;gap:8px;align-content:center;min-width:170px}\n.match{background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:6px 8px;font-size:12px}\n.match div{display:flex;justify-content:space-between}\n.match .w{color:var(--gold);font-weight:700}\n.ttl{--b:#fff;display:inline-flex;align-items:center;gap:6px;padding:3px 13px 3px 9px;border-radius:99px;border:1.5px solid var(--b);font-weight:800;font-size:13px;line-height:1.4;position:relative;overflow:hidden;white-space:nowrap;vertical-align:middle}\n.ttl svg{width:16px;height:16px;flex:none}\n.ttl.big{font-size:17px;padding:6px 18px 6px 12px}.ttl.big svg{width:21px;height:21px}\n.ttl.fx-shine::after{content:\"\";position:absolute;inset:0;background:linear-gradient(105deg,transparent 35%,rgba(255,255,255,.55) 50%,transparent 65%);transform:translateX(-120%);animation:ttlshine 2.6s ease-in-out infinite}\n@keyframes ttlshine{0%{transform:translateX(-120%)}60%,100%{transform:translateX(120%)}}\n.ttl.fx-glow{animation:ttlglow 2s ease-in-out infinite}\n@keyframes ttlglow{0%,100%{box-shadow:0 0 0 0 transparent}50%{box-shadow:0 0 12px 1px var(--b)}}\n.ttl.fx-pulse{animation:ttlpulse 1.6s ease-in-out infinite}\n@keyframes ttlpulse{0%,100%{transform:scale(1)}50%{transform:scale(1.06)}}\n.tgrid{display:grid;gap:12px;grid-template-columns:repeat(auto-fill,minmax(290px,1fr))}\n.tcard{display:grid;gap:10px;align-content:start}\n.tcard .pv{display:grid;gap:8px;justify-items:center;padding:14px 8px;background:#0d0805;border-radius:10px}\n.iconpick{display:flex;flex-wrap:wrap;gap:6px}.iconpick button{width:38px;height:38px;border-radius:9px;border:1px solid var(--line);background:#0d0805;color:var(--text);cursor:pointer;display:grid;place-items:center}\n.iconpick button.on{border-color:var(--gold);background:var(--panel2)}.iconpick svg{width:20px;height:20px}\ninput[type=color]{width:52px;height:36px;padding:2px;cursor:pointer}\n.login{max-width:360px;margin:12vh auto;padding:26px}\n.empty{padding:22px;text-align:center;color:var(--muted)}\n.navsec{font-size:10.5px;letter-spacing:1.2px;text-transform:uppercase;color:#7d6b52;padding:12px 12px 3px;font-weight:700}\n.navsec:first-of-type{padding-top:4px}\n.qs{margin:0 4px 6px;display:block}.qs input{width:100%;padding:7px 10px;font-size:13px}\n.lead{color:var(--muted);font-size:13.5px;max-width:860px;margin:2px 0 6px}\n.sec{margin-top:18px}\n.sec>h2{margin:0 0 4px}\n.sec>.help{color:var(--muted);font-size:12.5px;margin:0 0 10px;max-width:820px}\n.fgrid{display:grid;gap:14px 16px;grid-template-columns:repeat(auto-fill,minmax(230px,1fr))}\n.fld{display:grid;gap:4px;align-content:start}\n.fld>span.l{font-size:12.5px;color:var(--text);font-weight:600}\n.fld>span.h{font-size:11.5px;color:var(--muted);line-height:1.35}\n.fld input[type=number],.fld input[type=text],.fld select,.fld textarea{width:100%}\n.fld.changed input,.fld.changed select,.fld.changed textarea,.fld.changed .lst input{border-color:var(--gold);box-shadow:0 0 0 1px var(--gold) inset}\n.fld .hint{font-size:11.5px;color:var(--gold2);min-height:15px}\n.lst{display:grid;gap:6px}\n.lst .it{display:grid;grid-template-columns:auto 1fr auto;gap:6px;align-items:center}\n.lst .it b{font-size:11.5px;color:var(--muted);min-width:46px;font-weight:600}\n.lst .it input{width:100%}\n.lst .it .hint{grid-column:2}\n.lst{grid-template-columns:repeat(auto-fill,minmax(220px,1fr))}\n.xbtn{background:none;border:1px solid var(--line);border-radius:7px;color:var(--muted);cursor:pointer;width:28px;height:30px}\n.xbtn:hover{color:#fff;border-color:var(--bad)}\n.savebar{position:sticky;bottom:12px;margin-top:22px;display:flex;align-items:center;gap:12px;justify-content:space-between;background:#2a1c10;border:1px solid var(--gold2);border-radius:12px;padding:10px 14px;box-shadow:0 12px 30px rgba(0,0,0,.55);z-index:20}\n.savebar[hidden]{display:none}\n.savebar .msg{font-weight:700}\n.toggles{display:grid;gap:10px;grid-template-columns:repeat(auto-fill,minmax(210px,1fr))}\n.tog{display:flex;align-items:center;justify-content:space-between;gap:10px;background:#0d0805;border:1px solid var(--line);border-radius:10px;padding:10px 12px}\n.tog.off{border-color:var(--bad);background:rgba(212,87,74,.08)}\n.tog b{font-size:14px}.tog .sub{font-size:11.5px}\n.adrow{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}\n.adrow span{font-size:12px;padding:4px 9px;border-radius:8px;background:#0d0805;border:1px solid var(--line)}\n.adrow span.ad{background:rgba(243,205,98,.14);border-color:var(--gold2);color:var(--gold);font-weight:700}\n.livegrid{display:grid;gap:10px;grid-template-columns:repeat(auto-fill,minmax(260px,1fr))}\n.lt{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:10px 12px}\n.lt .top{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}\n.lt .seat{display:flex;justify-content:space-between;font-size:13px;padding:2px 0}\n.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--ok);margin-right:6px}\n.dot.off{background:#6b5a45}\n.tierrow td{padding:5px 8px}\n.tierrow select,.tierrow input{padding:4px 6px}\n@media (max-width:820px){.app{grid-template-columns:1fr}nav.side{position:static;height:auto;display:flex;overflow-x:auto;gap:4px;padding:8px}nav.side .brand,nav.side .navsec,nav.side .qs{display:none}nav.side a{white-space:nowrap}main{padding:16px}.savebar{bottom:6px}}\n</style>\n</head>\n<body>\n<div id=\"root\"></div>\n<script>\n'use strict';\nconst $ = (s, r = document) => r.querySelector(s);\nconst esc = v => String(v ?? '').replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nconst num = n => Number(n || 0).toLocaleString('en');\nconst short = n => { n = Number(n || 0); const a = Math.abs(n); return a >= 1e9 ? (n / 1e9).toFixed(a >= 1e10 ? 0 : 1) + 'B' : a >= 1e6 ? (n / 1e6).toFixed(a >= 1e7 ? 0 : 1) + 'M' : a >= 1e3 ? Math.round(n / 1e3) + 'K' : String(n); };\nconst cairo = new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', dateStyle: 'medium', timeStyle: 'short' });\nconst when = t => t ? cairo.format(new Date(t)) : '—';\nconst ago = t => { if (!t) return '—'; const s = (Date.now() - t) / 1000; return s < 90 ? 'now' : s < 3600 ? Math.round(s / 60) + ' min ago' : s < 86400 ? Math.round(s / 3600) + ' h ago' : Math.round(s / 86400) + ' d ago'; };\nconst DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];\nconst GAMES = { rotate: 'Each week in turn', domino: 'Dominoes', tawla: 'Backgammon (tawla)', chess: 'Chess', ludo: 'Ludo' };\nlet state = { view: 'overview', catalog: null, pending: 0 };\n\nconst ERRS = {\n  nobody_signed_up: 'Nobody has signed up for this tournament yet, so it can’t start. Use “Skip this one” to move to the next week.',\n  tourney_not_open: 'This tournament has already started or ended. The page is now up to date.',\n};\nasync function api(path, opts = {}) {\n  const r = await fetch('/api/admin' + path, { method: opts.method || (opts.body ? 'POST' : 'GET'), headers: { 'Content-Type': 'application/json' }, body: opts.body ? JSON.stringify(opts.body) : undefined, credentials: 'same-origin' });\n  const j = await r.json().catch(() => ({}));\n  if (r.status === 401) { showLogin(); throw new Error('Signed out'); }\n  if (!r.ok) throw new Error(ERRS[j.error] || j.error || ('HTTP ' + r.status));\n  return j;\n}\nfunction toast(msg, err) { const t = document.createElement('div'); t.className = 'toast' + (err ? ' err' : ''); t.textContent = msg; document.body.appendChild(t); setTimeout(() => t.remove(), err ? 4500 : 2400); }\nasync function act(fn, ok) { try { const r = await fn(); if (ok) toast(ok); return r; } catch (e) { if (e.message !== 'Signed out') toast(e.message, true); throw e; } }\n\n/* ---------------- titles: drawn the same way as in the game ---------------- */\nfunction iconSvg(name) { const d = (state.catalog?.icons || {})[name]; return d ? '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path fill=\"currentColor\" fill-rule=\"evenodd\" d=\"' + d + '\"/></svg>' : ''; }\nfunction badge(t, lang, big) {\n  if (!t) return '';\n  const s = t.style;\n  return '<span class=\"ttl fx-' + esc(s.effect) + (big ? ' big' : '') + '\" style=\"--b:' + esc(s.border) + ';background:linear-gradient(90deg,' + esc(s.bg[0]) + ',' + esc(s.bg[1]) + ');color:' + esc(s.fg) + '\"' + (lang === 'ar' ? ' dir=\"rtl\"' : '') + '>' + iconSvg(s.icon) + esc(lang === 'en' ? t.en : t.ar) + '</span>';\n}\nconst titleById = id => (state.catalog?.titles || []).find(t => t.id === id);\n\n/* ---------------- sign in ---------------- */\nfunction showLogin() {\n  $('#root').innerHTML = '<div class=\"card login\"><h1>Control room</h1><p class=\"sub\">Board Battles · enter the server\\'s ADMIN_KEY</p>' +\n    '<form id=\"lf\" class=\"row\" style=\"display:grid;gap:10px\"><input id=\"lk\" type=\"password\" placeholder=\"Admin key\" autocomplete=\"current-password\" required>' +\n    '<button class=\"btn gold\">Sign in</button><div id=\"le\" class=\"sub\"></div></form></div>';\n  $('#lf').onsubmit = async e => {\n    e.preventDefault();\n    try { await api('/login', { body: { key: $('#lk').value } }); start(); }\n    catch (er) { $('#le').textContent = er.message === 'admin_off' ? 'The dashboard is off: set ADMIN_KEY on the server.' : er.message === 'wrong_key' ? 'Wrong key.' : er.message; }\n  };\n  $('#lk').focus();\n}\n\n/* ---------------- the frame ---------------- */\n// the sidebar: [view, label] rows under section headings\nconst NAV = [\n  ['Now', [['overview', 'Overview'], ['live', 'Live tables'], ['analytics', 'Analytics']]],\n  ['Players', [['players', 'Players'], ['reports', 'Reports & support'], ['purchases', 'Purchases']]],\n  ['Engage', [['rewards', 'Push, gifts & notices'], ['events', 'Events'], ['tourney', 'Tournaments'], ['season', 'Season pass'], ['titles', 'Titles']]],\n  ['Game rules', [['games', 'Games & ads'], ['economy', 'Economy'], ['coinprizes', 'Prizes'], ['system', 'System']]],\n  ['', [['log', 'Activity log']]],\n];\n// the old Vodafone Cash money prizes: only listed while they are on or still have claims to settle\nconst VIEWS = NAV.flatMap(x => x[1]).concat([['prizes', 'Money prizes (Vodafone Cash)']]);\nconst ALIAS = { settings: 'system' };\nfunction frame() {\n  $('#root').innerHTML = '<div class=\"app\"><nav class=\"side\"><div class=\"brand\">♛ Board Battles<small>Control room</small></div>' +\n    '<form class=\"qs\" id=\"qsf\"><input id=\"qsi\" placeholder=\"Find a player…\" autocomplete=\"off\"></form>' +\n    NAV.map(([h, rows]) => (h ? '<div class=\"navsec\">' + h + '</div>' : '<div style=\"height:10px\"></div>') + rows.map(([k, l]) => '<a href=\"#' + k + '\" data-v=\"' + k + '\">' + l + '</a>').join('')).join('') +\n    '<a href=\"#prizes\" data-v=\"prizes\" id=\"moneynav\" hidden>Money prizes<span class=\"pill\" id=\"pendpill\" hidden></span></a>' +\n    '<a href=\"#\" id=\"logout\" style=\"margin-top:14px\">Sign out</a></nav><main id=\"main\"></main></div>';\n  $('#logout').onclick = async e => { e.preventDefault(); if (!leaveOk()) return; await api('/logout', { body: {} }).catch(() => {}); showLogin(); };\n  $('#qsf').onsubmit = e => { e.preventDefault(); state.q = $('#qsi').value.trim(); if (location.hash === '#players') go(); else location.hash = 'players'; };\n}\nfunction setPending(n) { state.pending = n; const p = $('#pendpill'); if (p) { p.hidden = !n; p.textContent = n; } const m = $('#moneynav'); if (m) m.hidden = !(n || state.moneyOn); }\n// unsaved changes on a settings page: asked before leaving it\nlet dirtyCheck = null;\nconst leaveOk = () => !dirtyCheck || !dirtyCheck() || confirm('You have unsaved changes on this page. Leave without saving?');\nwindow.addEventListener('beforeunload', e => { if (dirtyCheck && dirtyCheck()) { e.preventDefault(); e.returnValue = ''; } });\nlet lastHash = location.hash, liveTimer = null;\nasync function go() {\n  if (location.hash !== lastHash && !leaveOk()) { history.replaceState(null, '', lastHash || '#overview'); return; }\n  lastHash = location.hash; dirtyCheck = null;\n  if (liveTimer) { clearInterval(liveTimer); liveTimer = null; }\n  closeDrawer();\n  let v = (location.hash.slice(1) || 'overview').split('/')[0];\n  v = ALIAS[v] || v;\n  state.view = VIEWS.some(x => x[0] === v) ? v : 'overview';\n  document.querySelectorAll('nav.side a[data-v]').forEach(a => a.classList.toggle('on', a.dataset.v === state.view));\n  const main = $('#main'); main.innerHTML = '<div class=\"empty\">Loading…</div>';\n  try { await RENDER[state.view](main); } catch (e) { if (e.message !== 'Signed out') main.innerHTML = '<div class=\"card\">Could not load: ' + esc(e.message) + '</div>'; }\n}\nasync function start() {\n  frame();\n  try { state.catalog = await api('/catalog'); } catch { return; }\n  window.onhashchange = go;\n  go();\n  const tick = async () => { try { const o = await api('/overview'); state.moneyOn = o.flags.prizes; setPending(o.prizePending); } catch {} };\n  tick(); setInterval(tick, 60000);\n}\n\n/* ---------------- charts (plain SVG) ---------------- */\nfunction bars(rows, key, label, color) {\n  const W = 460, H = 150, P = 14, max = Math.max(1, ...rows.map(r => r[key]));\n  const bw = (W - P * 2) / rows.length;\n  let s = '<svg class=\"chart\" viewBox=\"0 0 ' + W + ' ' + (H + 34) + '\" role=\"img\" aria-label=\"' + esc(label) + '\">';\n  s += '<text x=\"0\" y=\"14\" fill=\"#b9a88a\" font-size=\"14\" font-weight=\"600\">' + esc(label) + ' · last ' + rows.length + ' days</text>';\n  rows.forEach((r, i) => {\n    const h = Math.round((r[key] / max) * (H - 40)), x = P + i * bw + 3, y = H - h;\n    s += '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + (bw - 6) + '\" height=\"' + Math.max(1, h) + '\" rx=\"3\" fill=\"' + color + '\"><title>' + esc(r.day) + ': ' + num(r[key]) + '</title></rect>';\n    if (r[key]) s += '<text x=\"' + (x + (bw - 6) / 2) + '\" y=\"' + (y - 4) + '\" fill=\"#f4e6c8\" font-size=\"11\" text-anchor=\"middle\">' + short(r[key]) + '</text>';\n    if ((i % 3 === 0 && i < rows.length - 2) || i === rows.length - 1) s += '<text x=\"' + (x + (bw - 6) / 2) + '\" y=\"' + (H + 18) + '\" fill=\"#b9a88a\" font-size=\"11\" text-anchor=\"middle\">' + esc(r.day.slice(5)) + '</text>';\n  });\n  return s + '<line x1=\"' + P + '\" x2=\"' + (W - P) + '\" y1=\"' + H + '\" y2=\"' + H + '\" stroke=\"#3a2a1e\"/></svg>';\n}\n\nconst RENDER = {};\n\n/* ---------------- overview ---------------- */\nRENDER.overview = async main => {\n  const o = await api('/overview');\n  setPending(o.prizePending);\n  const k = (v, l, alert) => '<div class=\"card kpi' + (alert ? ' alert' : '') + '\"><div class=\"v\">' + v + '</div><div class=\"l\">' + l + '</div></div>';\n  const f = (on, l, warn) => '<span class=\"flag ' + (warn && on ? 'warn' : on ? 'on' : 'off') + '\">' + l + ': ' + (on ? 'on' : 'off') + '</span>';\n  const t = o.tourney;\n  main.innerHTML = '<h1>Overview</h1><div class=\"sub\">Cairo time · updated ' + when(Date.now()) + '</div>' +\n    '<div class=\"flags\">' + f(o.flags.maintenance, 'Maintenance', true) + f(!!o.flags.notice, 'Notice') + f(t.enabled, 'Tournament') + f(o.flags.season, 'Season pass') + f(o.flags.push, 'Push') +\n      '<a class=\"flag\" href=\"#games\" style=\"text-decoration:none;color:inherit\">Ads between games: ' + (o.flags.adEvery ? (o.flags.adEvery === 1 ? 'every game' : '1 in ' + o.flags.adEvery) : 'off') + '</a>' +\n      (o.flags.gamesOff.length ? '<a class=\"flag warn\" href=\"#games\" style=\"text-decoration:none\">Off: ' + o.flags.gamesOff.map(g => GNAME[g] || g).join(', ') + '</a>' : '') +\n      (o.flags.minBuild ? '<a class=\"flag\" href=\"#system\" style=\"text-decoration:none;color:inherit\">Oldest app allowed: ' + o.flags.minBuild + '</a>' : '') +\n      (o.flags.prizes ? f(true, 'Money prizes') : '') + '</div>' +\n    '<div class=\"grid\">' +\n      '<a href=\"#live\" style=\"text-decoration:none;color:inherit\">' + k(num(o.live.online), 'Online now · ' + num(o.live.tables) + ' tables · ' + num(o.live.queued) + ' waiting ›') + '</a>' +\n      k(num(o.activeToday), 'Played today · ' + num(o.activeWeek) + ' this week') +\n      k(num(o.players), 'Players · ' + num(o.signedIn) + ' signed in · ' + num(o.newToday) + ' new today') +\n      k(num(o.gamesToday), 'Games today · fees ' + short(o.houseFeesToday) + ' coins') +\n      (o.flags.prizes || o.prizePending ? k(o.prizePending ? num(o.prizePending) + ' · ' + num(o.prizePendingEgp) + ' EGP' : '0', 'Money prizes to pay · ' + num(o.prizeUnclaimed) + ' waiting for a number', o.prizePending > 0) : '') +\n      k(num(o.seasonPremium), 'Season pass buyers this month') +\n      k(num(o.purchasesToday) + ' / ' + num(o.purchasesWeek), 'Store purchases today / this week') +\n      k(short(o.coinsHeld), 'Coins held by players') +\n      k(num(o.reportsWeek), 'Player reports this week · ' + num(o.support) + ' support messages', o.reportsWeek > 20) +\n      k(num(o.banned), 'Banned players') +\n    '</div>' +\n    '<div class=\"grid\" style=\"grid-template-columns:repeat(auto-fit,minmax(380px,1fr));margin-top:14px\">' +\n      '<div class=\"card\">' + bars(o.daily, 'active', 'Players who played', '#c9a25a') + '</div>' +\n      '<div class=\"card\">' + bars(o.daily, 'games', 'Games finished', '#4fae6a') + '</div>' +\n      '<div class=\"card\">' + bars(o.daily, 'newPlayers', 'New players', '#6f9fd8') + '</div>' +\n      (o.flags.prizes ? '<div class=\"card\">' + bars(o.daily, 'prizeEgp', 'Prizes paid (EGP)', '#e0a03a') + '</div>' : '') +\n    '</div>' +\n    '<h2>Next tournament</h2><div class=\"card row\" style=\"justify-content:space-between\"><div><b>' + esc(GAMES[t.game] || t.game) + '</b> · ' + esc(t.state) + ' · ' + when(t.startsAt) + '<div class=\"sub\">' + num(t.registered) + ' signed up</div></div><a class=\"btn\" href=\"#tourney\">Manage</a></div>' +\n    (o.flags.notice ? '<h2>Notice showing</h2><div class=\"card\">' + esc(o.flags.notice) + '</div>' : '');\n};\n\n/* ---------------- analytics ---------------- */\nconst MODE_GAME = m => /^(ffa|team)/.test(m) ? 'domino' : /^chess/.test(m) ? 'chess' : /^ludo/.test(m) ? 'ludo' : /^basra/.test(m) ? 'basra' : /^tarneeb/.test(m) ? 'tarneeb' : /^konkan/.test(m) ? 'konkan' : 'tawla';\nRENDER.analytics = async main => {\n  const days = Number((location.hash.split('/')[1])) || 30;\n  const d = await api('/analytics?days=' + days);\n  const pct = (a, b) => b ? Math.round(a / b * 100) + '%' : '—';\n  const cell = (n, of, ready) => !ready ? '<td class=\"num muted\">…</td>' : '<td class=\"num\" style=\"background:rgba(201,162,90,' + (of ? (n / of * 0.8).toFixed(2) : 0) + ')\">' + pct(n, of) + '<div class=\"sub\">' + n + '</div></td>';\n  // totals over the cohorts that are old enough\n  const sum = (k, r) => d.retention.filter(x => x[r]).reduce((a, x) => a + x[k], 0);\n  const joinedFor = r => d.retention.filter(x => x[r]).reduce((a, x) => a + x.joined, 0);\n  const games = { domino: [0, 0], tawla: [0, 0], chess: [0, 0], ludo: [0, 0], basra: [0, 0], tarneeb: [0, 0], konkan: [0, 0] };\n  d.games.online.forEach(r => games[MODE_GAME(r.mode)][0] += r.n);\n  d.games.practice.forEach(r => { if (games[r.game]) games[r.game][1] += r.n; });\n  const top = Math.max(1, ...d.funnel.map(f => f.n));\n  const hmax = Math.max(1, ...d.hours);\n  main.innerHTML = '<h1>Analytics</h1><div class=\"sub\">Who comes back, where new players drop off, what is played and when. Cairo time.</div>' +\n    '<div class=\"grid\" style=\"margin-top:12px\">' +\n      '<div class=\"card kpi\"><div class=\"v\">' + pct(sum('d1', 'd1Ready'), joinedFor('d1Ready')) + '</div><div class=\"l\">Come back the next day (day 1)</div></div>' +\n      '<div class=\"card kpi\"><div class=\"v\">' + pct(sum('d3', 'd3Ready'), joinedFor('d3Ready')) + '</div><div class=\"l\">Come back on day 3</div></div>' +\n      '<div class=\"card kpi\"><div class=\"v\">' + pct(sum('d7', 'd7Ready'), joinedFor('d7Ready')) + '</div><div class=\"l\">Come back on day 7</div></div>' +\n      '<div class=\"card kpi\"><div class=\"v\">' + num(d.retention.reduce((a, x) => a + x.joined, 0)) + '</div><div class=\"l\">New players, last 21 days</div></div>' +\n    '</div>' +\n    '<h2>New players: where they drop off</h2><div class=\"tabs\">' + [7, 30, 90].map(n => '<button data-days=\"' + n + '\" class=\"' + (n === d.days ? 'on' : '') + '\">Last ' + n + ' days</button>').join('') + '</div>' +\n    '<div class=\"card\">' + d.funnel.map((f, i) => '<div style=\"display:grid;grid-template-columns:260px 1fr 110px;gap:10px;align-items:center;margin:6px 0\"><div>' + esc(f.step) + '</div>' +\n      '<div style=\"background:var(--panel2);border-radius:6px;height:22px;overflow:hidden\"><div style=\"height:100%;width:' + (f.n / top * 100).toFixed(1) + '%;background:linear-gradient(90deg,#c9a25a,#f3cd62)\"></div></div>' +\n      '<div class=\"num\"><b>' + num(f.n) + '</b> <span class=\"sub\">' + (i ? pct(f.n, d.funnel[0].n) : '') + '</span></div></div>').join('') + '</div>' +\n    '<h2>Coming back, day by day</h2><div class=\"sub\" style=\"margin-bottom:8px\">Each row: the players who started that day, and how many opened the game again 1, 3 and 7 days later.</div>' +\n    '<div class=\"tablewrap\"><table><thead><tr><th>Started</th><th class=\"num\">Players</th><th class=\"num\">Day 1</th><th class=\"num\">Day 3</th><th class=\"num\">Day 7</th></tr></thead><tbody>' +\n      d.retention.slice().reverse().map(r => '<tr><td>' + esc(r.day) + '</td><td class=\"num\">' + num(r.joined) + '</td>' + cell(r.d1, r.joined, r.d1Ready) + cell(r.d3, r.joined, r.d3Ready) + cell(r.d7, r.joined, r.d7Ready) + '</tr>').join('') + '</tbody></table></div>' +\n    '<h2>What is played (last ' + Math.min(d.days, 30) + ' days)</h2><div class=\"grid\">' + Object.entries(games).map(([g, [on, pr]]) => '<div class=\"card kpi\"><div class=\"v\">' + num(on) + '</div><div class=\"l\">' + ({ domino: 'Dominoes', tawla: 'Backgammon', chess: 'Chess', ludo: 'Ludo', basra: 'Basra', tarneeb: 'Tarneeb', konkan: 'Konkan' })[g] + ' online · ' + num(pr) + ' vs the computer</div></div>').join('') + '</div>' +\n    '<div class=\"tablewrap\" style=\"margin-top:10px\"><table><thead><tr><th>Way to play</th><th class=\"num\">Online games</th></tr></thead><tbody>' + d.games.online.sort((a, b) => b.n - a.n).map(r => '<tr><td>' + esc(r.mode) + '</td><td class=\"num\">' + num(r.n) + '</td></tr>').join('') + '</tbody></table></div>' +\n    '<h2>When people play (online games by hour, last 14 days)</h2><div class=\"card\"><svg class=\"chart\" viewBox=\"0 0 640 160\" style=\"max-height:220px\">' +\n      d.hours.map((n, h) => { const bh = Math.round(n / hmax * 110), x = 14 + h * 26; return '<rect x=\"' + x + '\" y=\"' + (130 - bh) + '\" width=\"20\" height=\"' + Math.max(1, bh) + '\" rx=\"3\" fill=\"#c9a25a\"><title>' + h + ':00 · ' + n + '</title></rect>' + (h % 3 === 0 ? '<text x=\"' + (x + 10) + '\" y=\"148\" fill=\"#b9a88a\" font-size=\"11\" text-anchor=\"middle\">' + h + '</text>' : ''); }).join('') + '</svg>' +\n      '<div class=\"sub\">Busiest hour: ' + d.hours.indexOf(Math.max(...d.hours)) + ':00. A good time for the weekly tournament.</div></div>' +\n    '<h2>Players who played, last 30 days</h2><div class=\"card\" style=\"max-width:760px\">' + bars(d.daily, 'active', 'Players who played', '#c9a25a') + '</div>';\n  main.querySelectorAll('[data-days]').forEach(b => b.onclick = () => { location.hash = 'analytics/' + b.dataset.days; });\n};\n\n/* ---------------- prize requests ---------------- */\nRENDER.prizes = async main => {\n  const status = (location.hash.split('/')[1]) || 'pending';\n  const d = await api('/prizes?status=' + status);\n  const rules = d.rules;\n  const pend = d.rows.filter(r => r.status === 'pending');\n  if (status === 'pending') setPending(pend.length);\n  const GN = { domino: 'Dominoes', tawla: 'Backgammon', chess: 'Chess', ludo: 'Ludo', basra: 'Basra', tarneeb: 'Tarneeb', konkan: 'Konkan' };\n  const monthName = m => { const [y, mo] = m.split('-').map(Number); return new Date(Date.UTC(y, mo - 1, 15)).toLocaleString('en', { month: 'long', year: 'numeric' }); };\n  const LABEL = { pending: 'To pay', unclaimed: 'Waiting for a number', paid: 'Paid', rejected: 'Rejected', expired: 'Expired', all: 'All' };\n  main.innerHTML = '<h1>Monthly prizes · Vodafone Cash</h1>' +\n    '<div class=\"sub\">On the 1st of each month, the top player of each game\\'s monthly leaderboard (at least ' + d.minGames + ' online games) wins <b>' + num(rules.egp) + ' EGP</b> and the \"player of the month\" title. ' +\n      'The winner enters a Vodafone Cash number (' + esc(rules.prefixes.join(', ')) + ') in the game within ' + rules.claimDays + ' days. Prizes are <b>' + (rules.enabled ? 'on' : 'off') + '</b> (<a href=\"#settings\">change</a>) · this month\\'s race is on the <a href=\"#titles\">Titles</a> page.</div>' +\n    '<div class=\"tabs\">' + Object.keys(LABEL).map(s => '<button data-s=\"' + s + '\" class=\"' + (s === status ? 'on' : '') + '\">' + LABEL[s] + '</button>').join('') + '</div>' +\n    (status === 'pending' && pend.length ? '<div class=\"card\" style=\"margin-bottom:12px\">To pay: <b>' + pend.length + '</b> · <b>' + num(pend.reduce((a, r) => a + r.egp, 0)) + ' EGP</b>. Send the money on Vodafone Cash, then press <b>Paid</b> (the winner gets a notification). <b>Ask again</b> if the number is wrong; <b>Reject</b> if the win broke the rules (cheating, several accounts).</div>' : '') +\n    (d.rows.length ? '<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>Month</th><th>Game</th><th>Winner</th><th>Vodafone Cash</th><th class=\"num\">EGP</th><th>Status</th><th></th></tr></thead><tbody>' +\n      d.rows.map(r => '<tr><td class=\"mono\">' + r.id + '</td><td>' + esc(monthName(r.month)) + '</td><td>' + esc(GN[r.game] || r.game) + '</td><td><a href=\"#players/' + esc(r.user_id) + '\" data-player=\"' + esc(r.user_id) + '\">' + esc(r.name || '—') + '</a><div class=\"sub\">won ' + when(r.ts) + '</div></td>' +\n        '<td>' + (r.phone ? '<b class=\"mono\" style=\"font-size:14px\">' + esc(r.phone) + '</b> <button class=\"btn sm\" data-copy=\"' + esc(r.phone) + '\">Copy</button>' : '<span class=\"muted\">not given yet</span>') + '</td><td class=\"num\"><b>' + num(r.egp) + '</b></td>' +\n        '<td><span class=\"tag ' + (r.status === 'unclaimed' ? '' : r.status === 'expired' ? 'rejected' : r.status) + '\">' + (LABEL[r.status] || r.status) + '</span>' + (r.done_ts ? '<div class=\"sub\">' + when(r.done_ts) + '</div>' : '') + (r.note ? '<div class=\"sub\">' + esc(r.note) + '</div>' : '') + '</td>' +\n        '<td>' + (r.status === 'pending' ? '<div class=\"row\"><button class=\"btn sm ok\" data-pay=\"' + r.id + '\" data-egp=\"' + r.egp + '\" data-phone=\"' + esc(r.phone) + '\">Paid</button><button class=\"btn sm\" data-again=\"' + r.id + '\">Ask again</button><button class=\"btn sm bad\" data-rej=\"' + r.id + '\">Reject</button></div>'\n          : r.status === 'unclaimed' ? '<button class=\"btn sm bad\" data-rej=\"' + r.id + '\">Reject</button>' : '') + '</td></tr>').join('') +\n      '</tbody></table></div>' : '<div class=\"card empty\">Nothing here</div>');\n  main.querySelectorAll('[data-s]').forEach(b => b.onclick = () => { location.hash = 'prizes/' + b.dataset.s; });\n  main.querySelectorAll('[data-copy]').forEach(b => b.onclick = () => { navigator.clipboard.writeText(b.dataset.copy); toast('Copied ' + b.dataset.copy); });\n  const settle = (id, action, note, ok) => act(() => api('/prizes/' + id, { body: { action, note } }), ok).then(go);\n  main.querySelectorAll('[data-pay]').forEach(b => b.onclick = () => { const note = prompt('Sent ' + b.dataset.egp + ' EGP to ' + b.dataset.phone + '?\\nTransaction number (optional):', ''); if (note !== null) settle(b.dataset.pay, 'paid', note, 'Marked paid · the winner was told'); });\n  main.querySelectorAll('[data-again]').forEach(b => b.onclick = () => { const note = prompt('Ask the winner for their number again?\\nWhat was wrong (they see it):', 'الرقم مش على فودافون كاش'); if (note !== null) settle(b.dataset.again, 'again', note, 'The winner was asked again'); });\n  main.querySelectorAll('[data-rej]').forEach(b => b.onclick = () => { const note = prompt('Reject this prize for good?\\nReason (the winner sees it):', ''); if (note !== null) settle(b.dataset.rej, 'reject', note, 'Rejected'); });\n  main.querySelectorAll('[data-player]').forEach(a => a.onclick = e => { e.preventDefault(); openPlayer(a.dataset.player); });\n};\n\n/* ---------------- players ---------------- */\nRENDER.players = async main => {\n  const parts = location.hash.split('/'), open = parts[1];\n  main.innerHTML = '<h1>Players</h1><div class=\"sub\">Search by name, friend code, player id, e-mail or phone</div>' +\n    '<form id=\"sf\" class=\"row\" style=\"margin:12px 0\"><input id=\"sq\" placeholder=\"Search players\" style=\"min-width:280px\" value=\"' + esc(state.q || '') + '\"><button class=\"btn gold\">Search</button></form><div id=\"pl\"></div>';\n  const load = async () => {\n    const d = await api('/players?q=' + encodeURIComponent(state.q || ''));\n    $('#pl').innerHTML = d.rows.length ? '<div class=\"tablewrap\"><table><thead><tr><th>Player</th><th>Sign-in</th><th class=\"num\">Coins</th><th class=\"num\">Games</th><th class=\"num\">Win %</th><th>Joined</th><th>Last seen</th><th></th></tr></thead><tbody>' +\n      d.rows.map(u => '<tr class=\"click\" data-id=\"' + esc(u.id) + '\"><td><b>' + esc(u.name) + '</b>' + (u.online ? ' <span class=\"tag on\">online</span>' : '') + (u.banned ? ' <span class=\"tag banned\">banned</span>' : '') + (u.muted ? ' <span class=\"tag\">muted</span>' : '') +\n        '<div class=\"sub mono\">' + esc(u.code || u.pid || u.id) + '</div></td><td><span class=\"tag ' + u.login + '\">' + u.login + '</span><div class=\"sub\">' + esc(u.contact) + '</div></td>' +\n        '<td class=\"num\">' + short(u.coins) + '</td><td class=\"num\">' + num(u.games) + '</td><td class=\"num\">' + (u.games ? Math.round(u.wins / u.games * 100) : 0) + '%</td><td>' + when(u.created) + '</td><td>' + ago(u.seen) + '</td><td>›</td></tr>').join('') +\n      '</tbody></table></div>' : '<div class=\"card empty\">No players found</div>';\n    $('#pl').querySelectorAll('tr[data-id]').forEach(tr => tr.onclick = () => openPlayer(tr.dataset.id));\n  };\n  $('#sf').onsubmit = e => { e.preventDefault(); state.q = $('#sq').value; load(); };\n  await load();\n  if (open) openPlayer(open);\n};\n\nasync function openPlayer(id) {\n  closeDrawer();\n  const sh = document.createElement('div'); sh.className = 'shade'; sh.onclick = closeDrawer;\n  const dr = document.createElement('div'); dr.className = 'drawer'; dr.innerHTML = '<div class=\"empty\">Loading…</div>';\n  document.body.append(sh, dr);\n  const render = async () => {\n    const d = await api('/players/' + encodeURIComponent(id));\n    const u = d.user, s = d.stats || {}, r = d.row;\n    const skins = state.catalog.skins.filter(k => !k.free && !d.skins.includes(k.id));\n    dr.innerHTML = '<button class=\"btn sm x\" id=\"cx\">Close ✕</button><h1>' + esc(u.name) + '</h1>' + (d.title ? '<div style=\"margin:4px 0 6px\">' + badge(titleById(d.title), 'en') + '</div>' : '') +\n      '<div class=\"sub mono\">' + esc(u.id) + ' · code ' + esc(r.code || '—') + ' · ' + r.login + (r.contact ? ' · ' + esc(r.contact) : '') + '</div>' +\n      '<div class=\"flags\">' + (d.online ? '<span class=\"flag on\">online</span>' : '<span class=\"flag off\">last seen ' + ago(u.seen) + '</span>') + (r.banned ? '<span class=\"flag warn\">banned: ' + esc(u.ban_reason || '') + '</span>' : '') + (r.muted ? '<span class=\"flag warn\">muted</span>' : '') + (d.season.premium ? '<span class=\"flag on\">season premium</span>' : '') + '</div>' +\n      '<div class=\"grid\">' +\n        '<div class=\"card kpi\"><div class=\"v\">' + num(u.coins) + '</div><div class=\"l\">Coins</div></div>' +\n        '<div class=\"card kpi\"><div class=\"v\">' + num(s.games) + '</div><div class=\"l\">Games · ' + num(s.wins) + ' won · ' + (s.winRate || 0) + '%</div></div>' +\n        '<div class=\"card kpi\"><div class=\"v\">' + short(s.net) + '</div><div class=\"l\">Net from games · won ' + short(s.coinsWon) + ' / lost ' + short(s.coinsLost) + '</div></div>' +\n        '<div class=\"card kpi\"><div class=\"v\">' + (s.level || 1) + '</div><div class=\"l\">Level · season tier ' + d.season.tier + ' (' + d.season.sp + ' SP)</div></div>' +\n      '</div>' +\n      '<h2>Actions</h2><div class=\"card\" style=\"display:grid;gap:10px\">' +\n        '<div class=\"row\"><input id=\"pc\" type=\"number\" placeholder=\"Coins (− takes)\" style=\"width:170px\"><input id=\"pr\" placeholder=\"Reason (log)\"><button class=\"btn gold\" id=\"bc\">Give / take coins</button></div>' +\n        '<div class=\"row\"><select id=\"ps\"><option value=\"\">Give a skin…</option>' + skins.map(k => '<option value=\"' + k.id + '\">' + esc(k.cat + ' · ' + k.id) + (k.pass ? ' (season)' : '') + '</option>').join('') + '</select><button class=\"btn\" id=\"bs\">Give skin</button>' +\n          '<button class=\"btn\" id=\"bp\">' + (d.season.premium ? 'Remove season premium' : 'Give season premium') + '</button><input id=\"psp\" type=\"number\" placeholder=\"Season points\" value=\"' + d.season.sp + '\"><button class=\"btn\" id=\"bsp\">Set SP</button></div>' +\n        '<div class=\"row\"><input id=\"pn\" placeholder=\"New name\" value=\"' + esc(u.name) + '\"><button class=\"btn\" id=\"bn\">Rename</button>' +\n          (r.muted ? '<button class=\"btn\" id=\"bum\">Unmute</button>' : '<button class=\"btn\" id=\"bm\">Mute 24 h</button>') +\n          (r.banned ? '<button class=\"btn ok\" id=\"bub\">Unban</button>' : '<button class=\"btn bad\" id=\"bb\">Ban</button>') + '</div>' +\n        '<div class=\"row\"><input id=\"pt\" placeholder=\"Push title\" style=\"width:180px\"><input id=\"px\" placeholder=\"Push message to this player\" style=\"flex:1;min-width:220px\"><button class=\"btn\" id=\"bx\">Send</button></div>' +\n        '<div class=\"row\"><button class=\"btn bad sm\" id=\"bd\">Delete account</button><span class=\"sub\">Removes the player and everything they have. Can\\'t be undone.</span></div>' +\n      '</div>' +\n      '<h2>Coin history</h2>' + (d.coins.length ? '<div class=\"tablewrap\"><table><thead><tr><th>When</th><th>What</th><th class=\"num\">Change</th><th class=\"num\">Balance</th></tr></thead><tbody>' +\n        d.coins.map(c => '<tr><td>' + when(c.ts) + '</td><td>' + esc(c.kind) + (c.mode ? ' · ' + esc(c.mode) : '') + (c.stake ? ' · stake ' + short(c.stake) : '') + '</td><td class=\"num\" style=\"color:' + (c.delta >= 0 ? '#9fe0b0' : '#ff9d92') + '\">' + (c.delta >= 0 ? '+' : '') + num(c.delta) + '</td><td class=\"num\">' + num(c.balance) + '</td></tr>').join('') + '</tbody></table></div>' : '<div class=\"card empty\">None</div>') +\n      '<h2>Monthly prizes</h2>' + (d.prizes.length ? '<table><tbody>' + d.prizes.map(c => '<tr><td>#' + c.id + '</td><td>' + esc(c.month) + ' · ' + esc(c.game) + '</td><td class=\"mono\">' + esc(c.phone || '—') + '</td><td class=\"num\">' + num(c.egp) + ' EGP</td><td><span class=\"tag ' + c.status + '\">' + c.status + '</span></td></tr>').join('') + '</tbody></table>' : '<div class=\"card empty\">None</div>') +\n      '<h2>Purchases</h2>' + (d.purchases.length ? '<table><tbody>' + d.purchases.map(p => '<tr><td>' + when(p.ts) + '</td><td>' + esc(p.product) + '</td><td class=\"mono\">' + esc(p.order_id || '') + '</td></tr>').join('') + '</tbody></table>' : '<div class=\"card empty\">None</div>') +\n      '<h2>Skins (' + d.skins.length + ')</h2><div class=\"card\">' + (d.skins.map(k => '<span class=\"tag\" style=\"margin:2px\">' + esc(k) + ' <a href=\"#\" data-unskin=\"' + esc(k) + '\" title=\"Take back\">✕</a></span>').join('') || '<span class=\"muted\">Only the free ones</span>') + '</div>' +\n      '<h2>Titles</h2><div class=\"card\" style=\"display:grid;gap:10px\">' + (d.titles.length ? '<div class=\"row\">' + d.titles.map(t => '<span>' + badge(titleById(t.id), 'en') + (d.title === t.id ? ' <span class=\"tag on\">wearing</span>' : '') + (t.until ? ' <span class=\"sub\">until ' + when(t.until) + '</span>' : '') + ' <a href=\"#\" data-untitle=\"' + esc(t.id) + '\" title=\"Take back\">✕</a></span>').join('') + '</div>' : '<span class=\"muted\">No titles</span>') +\n        '<div class=\"row\"><select id=\"pti\"><option value=\"\">Give a title…</option>' + state.catalog.titles.filter(t => !t.monthly).map(t => '<option value=\"' + t.id + '\">' + esc(t.en + ' · ' + t.ar) + '</option>').join('') + '</select><select id=\"ptd\"><option value=\"0\">for good</option><option value=\"7\">7 days</option><option value=\"30\">30 days</option><option value=\"90\">90 days</option></select><button class=\"btn\" id=\"bti\">Give title</button></div></div>' +\n      '<h2>Reports about this player (' + d.reportsAbout.length + ')</h2>' + (d.reportsAbout.length ? '<table><tbody>' + d.reportsAbout.map(x => '<tr><td>' + when(x.ts) + '</td><td>' + esc(x.reason) + '</td><td>by ' + esc(x.from_name || x.from_id) + '</td></tr>').join('') + '</tbody></table>' : '<div class=\"card empty\">None</div>');\n    const post = (body, ok) => act(() => api('/players/' + encodeURIComponent(id), { body }), ok).then(render);\n    $('#cx', dr).onclick = closeDrawer;\n    $('#bc', dr).onclick = () => { const a = Number($('#pc', dr).value); if (!a) return toast('Enter an amount', true); if (Math.abs(a) >= 10000000 && !confirm('That is ' + num(a) + ' coins. Sure?')) return; post({ action: 'coins', amount: a, reason: $('#pr', dr).value }, (a > 0 ? 'Gave ' : 'Took ') + num(Math.abs(a)) + ' coins'); };\n    $('#bs', dr).onclick = () => { const k = $('#ps', dr).value; if (k) post({ action: 'skin', skin: k }, 'Skin given'); };\n    $('#bp', dr).onclick = () => post({ action: d.season.premium ? 'unpremium' : 'premium' }, 'Season pass updated');\n    $('#bsp', dr).onclick = () => post({ action: 'sp', sp: Number($('#psp', dr).value) }, 'Season points set');\n    $('#bn', dr).onclick = () => post({ action: 'rename', name: $('#pn', dr).value }, 'Renamed');\n    if ($('#bm', dr)) $('#bm', dr).onclick = () => post({ action: 'mute', hours: 24 }, 'Muted for 24 h');\n    if ($('#bum', dr)) $('#bum', dr).onclick = () => post({ action: 'unmute' }, 'Unmuted');\n    if ($('#bb', dr)) $('#bb', dr).onclick = () => { const why = prompt('Ban ' + u.name + '? Reason (they see it):', ''); if (why !== null) post({ action: 'ban', reason: why }, 'Banned'); };\n    if ($('#bub', dr)) $('#bub', dr).onclick = () => post({ action: 'unban' }, 'Unbanned');\n    $('#bx', dr).onclick = () => { const t = $('#px', dr).value; if (t) post({ action: 'notify', title: $('#pt', dr).value, text: t }, 'Sent'); };\n    $('#bd', dr).onclick = () => { if (prompt('Type DELETE to delete ' + u.name + ' for good') === 'DELETE') act(() => api('/players/' + encodeURIComponent(id), { body: { action: 'delete' } }), 'Deleted').then(() => { closeDrawer(); go(); }); };\n    $('#bti', dr).onclick = () => { const k = $('#pti', dr).value; if (k) post({ action: 'title', title: k, days: Number($('#ptd', dr).value) }, 'Title given'); };\n    dr.querySelectorAll('[data-untitle]').forEach(a => a.onclick = e => { e.preventDefault(); if (confirm('Take back this title?')) post({ action: 'untitle', title: a.dataset.untitle }, 'Title taken back'); });\n    dr.querySelectorAll('[data-unskin]').forEach(a => a.onclick = e => { e.preventDefault(); if (confirm('Take back ' + a.dataset.unskin + '?')) post({ action: 'unskin', skin: a.dataset.unskin }, 'Skin taken back'); });\n  };\n  try { await render(); } catch (e) { dr.innerHTML = '<button class=\"btn sm x\" onclick=\"closeDrawer()\">Close ✕</button><div class=\"card\">' + esc(e.message) + '</div>'; }\n}\nfunction closeDrawer() { document.querySelectorAll('.drawer,.shade').forEach(x => x.remove()); }\ndocument.addEventListener('keydown', e => { if (e.key === 'Escape') closeDrawer(); });\n\n/* ---------------- rewards and notices ---------------- */\nRENDER.rewards = async main => {\n  const st = await api('/settings'), ps = await api('/push');\n  const live = st.notice.until > Date.now() && st.notice.text;\n  main.innerHTML = '<h1>Rewards & notices</h1>' +\n    '<h2>Push notification</h2><div class=\"card\"' + (ps.on ? '' : ' style=\"border-color:var(--warn)\"') + '><div class=\"sub\" style=\"margin-bottom:8px\">' +\n      (ps.on ? num(ps.players) + ' players can get one (' + num(ps.phones) + ' phones): ' + num(ps.week) + ' played this week, ' + num(ps.month) + ' this month, ' + num(ps.signed) + ' signed in.'\n        : 'Push is off on the server (no FIREBASE_SERVICE_ACCOUNT).') + ' Each player gets it in their language; leave English empty to send the Arabic to everyone.</div>' +\n      '<div class=\"form\"><label class=\"f\">Title (Arabic)<input id=\"pta\" maxlength=\"80\" placeholder=\"بورد باتلز\"></label>' +\n      '<label class=\"f\">Title (English)<input id=\"pte\" maxlength=\"80\" placeholder=\"Board Battles\"></label>' +\n      '<label class=\"f\">Message (Arabic)<textarea id=\"pba\" rows=\"2\" maxlength=\"300\" placeholder=\"ادخل العب دور…\"></textarea></label>' +\n      '<label class=\"f\">Message (English)<textarea id=\"pbe\" rows=\"2\" maxlength=\"300\" placeholder=\"Come and play a round…\"></textarea></label>' +\n      '<label class=\"f\">Who<select id=\"pw\"><option value=\"7\">Played in the last 7 days</option><option value=\"30\">Played in the last 30 days</option><option value=\"signed\">Signed-in players</option><option value=\"all\">Everyone with the app</option></select></label>' +\n      '<label class=\"f\">Test on one player first (friend code or id)<input id=\"pp\" placeholder=\"optional\"></label></div>' +\n      '<div class=\"row\" style=\"margin-top:12px\"><button class=\"btn\" id=\"pst\"' + (ps.on ? '' : ' disabled') + '>Send the test</button><button class=\"btn gold\" id=\"psa\"' + (ps.on ? '' : ' disabled') + '>Send to the group</button></div></div>' +\n    '<h2>Coins for everyone</h2><div class=\"card\"><div class=\"form\">' +\n      '<label class=\"f\">Coins each<input id=\"gc\" type=\"number\" min=\"1\" placeholder=\"e.g. 50000\"></label>' +\n      '<label class=\"f\">Who<select id=\"ga\"><option value=\"7\">Played in the last 7 days</option><option value=\"30\">Played in the last 30 days</option><option value=\"0\">Every player</option></select></label>' +\n      '<label class=\"f\" style=\"grid-column:1/-1\">Message (shown in the game and as a push)<input id=\"gm\" placeholder=\"هدية بمناسبة… · A gift for…\"></label>' +\n    '</div><div class=\"row\" style=\"margin-top:12px\"><label class=\"switch\"><input type=\"checkbox\" id=\"gp\" checked> Send a push notification</label><button class=\"btn gold\" id=\"gb\">Send the gift</button></div></div>' +\n    '<h2>Notice in the game</h2><div class=\"card\"><div class=\"sub\" style=\"margin-bottom:8px\">Shown to every player when they open the game (and right away to those playing now). ' + (live ? 'Showing now until ' + when(st.notice.until) + '.' : 'Nothing showing.') + '</div>' +\n      '<div class=\"form\"><label class=\"f\" style=\"grid-column:1/-1\">Text<textarea id=\"nt\" rows=\"2\" maxlength=\"400\">' + esc(live ? st.notice.text : '') + '</textarea></label>' +\n      '<label class=\"f\">Show for (hours)<input id=\"nh\" type=\"number\" value=\"24\" min=\"1\" max=\"720\"></label></div>' +\n      '<div class=\"row\" style=\"margin-top:12px\"><label class=\"switch\"><input type=\"checkbox\" id=\"np\"> Also a push to players of the last 30 days</label><button class=\"btn gold\" id=\"nb\">Show notice</button>' + (live ? '<button class=\"btn\" id=\"nc\">Take it down</button>' : '') + '</div></div>' +\n    '<h2>Daily reward, ads and prizes</h2><div class=\"card\"><div class=\"sub\">Daily streak: ' + st.economy.streak.map(short).join(' · ') + ' · rewarded ad: ' + short(st.economy.adReward) + ' (' + st.economy.adsPerDay + ' a day) · weekly prize: ' + st.economy.weeklyPrizes.map(short).join(' · ') + ' · monthly top earners: ' + st.economy.monthlyPrizes.map(short).join(' · ') + '</div><a class=\"btn\" href=\"#economy\" style=\"display:inline-block;margin-top:10px\">Change them</a></div>';\n  const pushBody = () => ({ titleAr: $('#pta').value, titleEn: $('#pte').value, bodyAr: $('#pba').value, bodyEn: $('#pbe').value });\n  $('#pst').onclick = async () => {\n    if (!$('#pp').value.trim()) return toast('Enter a friend code or player id to test on', true);\n    if (!$('#pba').value.trim() && !$('#pbe').value.trim()) return toast('Write the message first', true);\n    const r = await act(() => api('/push', { body: { ...pushBody(), player: $('#pp').value.trim() } }));\n    toast(r.phones ? 'Sent to their ' + r.phones + ' phone(s)' : 'That player has no phone registered for push', !r.phones);\n  };\n  $('#psa').onclick = async () => {\n    if (!$('#pba').value.trim() && !$('#pbe').value.trim()) return toast('Write the message first', true);\n    const w = $('#pw'), label = w.options[w.selectedIndex].text;\n    if (!confirm('Send this push to: ' + label + '?')) return;\n    const r = await act(() => api('/push', { body: { ...pushBody(), audience: w.value } }));\n    toast('Sent to ' + num(r.players) + ' players (' + num(r.phones) + ' phones)');\n  };\n  $('#gb').onclick = async () => {\n    const c = Number($('#gc').value), days = Number($('#ga').value);\n    if (!(c > 0)) return toast('Enter the coins', true);\n    if (!confirm('Give ' + num(c) + ' coins to ' + (days ? 'everyone who played in the last ' + days + ' days' : 'every player') + '?')) return;\n    const r = await act(() => api('/rewards', { body: { coins: c, activeDays: days, message: $('#gm').value, push: $('#gp').checked } }));\n    toast('Sent to ' + num(r.players) + ' players');\n  };\n  $('#nb').onclick = async () => { await act(() => api('/notice', { body: { text: $('#nt').value, hours: Number($('#nh').value), push: $('#np').checked } }), 'Notice is showing'); go(); };\n  if ($('#nc')) $('#nc').onclick = async () => { await act(() => api('/notice', { body: { text: '' } }), 'Notice taken down'); go(); };\n};\n\n/* ---------------- tournaments ---------------- */\nRENDER.tourney = async main => {\n  const d = await api('/tourney'), v = d.view, t = d.settings;\n  const who = e => e ? esc(e.name) + (e.bot ? ' <span class=\"muted\">(cpu)</span>' : '') : '<span class=\"muted\">—</span>';\n  const on = !!t.enabled;\n  main.innerHTML = '<h1>Tournaments</h1>' +\n    '<div class=\"card row\" style=\"justify-content:space-between;margin-bottom:12px\"><div><b>Tournaments in the game</b><div class=\"sub\">' +\n      (on ? 'On: players see the tournament, sign up, and it starts by itself every ' + DAYS[t.weekday] + ' at ' + t.hour + ':00.' : 'Off: hidden in the game and none start. Sign-ups are kept for when you switch it back on.') +\n      '</div></div><label class=\"switch\"><input type=\"checkbox\" id=\"ton\"' + (on ? ' checked' : '') + '><b>' + (on ? 'On' : 'Off') + '</b></label></div>' +\n    '<div class=\"card row\" style=\"justify-content:space-between' + (on ? '' : ';opacity:.6') + '\"><div><b>' + esc(GAMES[v.game] || v.game) + '</b> · <span class=\"tag ' + (v.state === 'running' ? 'pending' : '') + '\">' + (on || v.state !== 'open' ? v.state : 'off') + '</span> · starts ' + when(v.startsAt) +\n      '<div class=\"sub\">' + num(v.count) + (v.state === 'open' ? ' signed up' : ' places in the bracket') + ' · prizes ' + v.prizes.map(short).join(' · ') + '</div></div>' +\n      '<div class=\"row\">' + (v.state === 'open' && on ? '<button class=\"btn gold\" id=\"ts\">Start now</button>' : '') + (v.state !== 'done' ? '<button class=\"btn bad\" id=\"tc\">' + (v.state === 'running' ? 'Stop' : 'Skip this one') + '</button>' : '') + '</div></div>' +\n    (v.rounds.length ? '<h2>Bracket</h2><div class=\"bracket\">' + v.rounds.map((r, i) => '<div class=\"round\"><div class=\"sub\">' + (i === v.rounds.length - 1 ? 'Final' : i === v.rounds.length - 2 ? 'Semi-finals' : 'Round ' + (i + 1)) + '</div>' +\n      r.map(m => '<div class=\"match\"><div class=\"' + (m.winner === 0 ? 'w' : '') + '\">' + who(m.a) + '</div><div class=\"' + (m.winner === 1 ? 'w' : '') + '\">' + who(m.b) + '</div>' + (m.live ? '<div class=\"sub\">playing…</div>' : '') + '</div>').join('') + '</div>').join('') + '</div>' : '') +\n    (v.results.length ? '<h2>Results</h2><table><tbody>' + v.results.map(x => '<tr><td>#' + x.place + '</td><td>' + esc(x.name) + '</td><td class=\"num\">' + num(x.coins) + '</td></tr>').join('') + '</tbody></table>' : '') +\n    '<h2>Settings</h2><div class=\"card\"><div class=\"form\">' +\n      '<label class=\"f\">Day (Cairo)<select id=\"tw\">' + DAYS.map((x, i) => '<option value=\"' + i + '\"' + (i === t.weekday ? ' selected' : '') + '>' + x + '</option>').join('') + '</select></label>' +\n      '<label class=\"f\">Hour (0–23, Cairo)<input id=\"th\" type=\"number\" min=\"0\" max=\"23\" value=\"' + t.hour + '\"></label>' +\n      '<label class=\"f\">Game<select id=\"tg\">' + Object.entries(GAMES).map(([k, l]) => '<option value=\"' + k + '\"' + (k === t.game ? ' selected' : '') + '>' + l + '</option>').join('') + '</select></label>' +\n      t.prizes.map((p, i) => '<label class=\"f\">Prize #' + (i + 1) + (i >= 4 ? ' (5th–8th)' : '') + '<input type=\"number\" min=\"0\" class=\"tp\" value=\"' + p + '\"></label>').join('') +\n      '<label class=\"f\">Everyone who played<input id=\"tpl\" type=\"number\" min=\"0\" value=\"' + t.played + '\"></label>' +\n    '</div><button class=\"btn gold\" id=\"tsv\" style=\"margin-top:12px\">Save tournament settings</button></div>' +\n    '<h2>Signed up (' + d.registered.length + ')</h2>' + (d.registered.length ? '<div class=\"card\">' + d.registered.map(r => '<a href=\"#players/' + esc(r.id) + '\" class=\"tag\" style=\"margin:2px;text-decoration:none\">' + esc(r.name) + (r.online ? ' ●' : '') + '</a>').join('') + '</div>' : '<div class=\"card empty\">Nobody yet</div>') +\n    '<h2>Past tournaments</h2>' + (d.history.length ? '<table><thead><tr><th>Date</th><th>Game</th><th class=\"num\">People</th><th>Winner</th><th>2nd</th></tr></thead><tbody>' +\n      d.history.map(h => '<tr><td>' + esc(h.event) + '</td><td>' + esc(GAMES[h.game] || h.game) + '</td><td class=\"num\">' + num(h.people) + '</td><td>' + esc(h.results?.[0]?.name || '—') + '</td><td>' + esc(h.results?.[1]?.name || '—') + '</td></tr>').join('') + '</tbody></table>' : '<div class=\"card empty\">None yet</div>');\n  if ($('#ts')) $('#ts').onclick = async () => {\n    if (!v.count) return toast(ERRS.nobody_signed_up, true);\n    if (!confirm('Start the tournament now with ' + v.count + ' player' + (v.count === 1 ? '' : 's') + '? Empty places get computer players.')) return;\n    try { await act(() => api('/tourney', { body: { action: 'start' } }), 'Tournament started'); } finally { go(); }\n  };\n  $('#ton').onchange = async e => {\n    const want = e.target.checked;\n    if (!want && !confirm('Switch tournaments off? They disappear from the game and none start until you switch them back on.' + (v.state === 'running' ? ' The one running now still plays to the end.' : ''))) { e.target.checked = true; return; }\n    try { await act(() => api('/settings', { method: 'PUT', body: { tourney: { enabled: want } } }), want ? 'Tournaments are on' : 'Tournaments are off'); } catch { e.target.checked = !want; return; }\n    go();\n  };\n  if ($('#tc')) $('#tc').onclick = async () => {\n    if (!confirm(v.state === 'running' ? 'Stop the running tournament? Nobody is paid, and the next one opens.' : 'Skip this tournament? Its sign-ups are dropped and the next week’s opens.')) return;\n    try { await act(() => api('/tourney', { body: { action: 'cancel' } }), v.state === 'running' ? 'Tournament stopped' : 'Skipped: the next tournament is open'); } finally { go(); }\n  };\n  $('#tsv').onclick = async () => {\n    await act(() => api('/settings', { method: 'PUT', body: { tourney: { weekday: Number($('#tw').value), hour: Number($('#th').value), game: $('#tg').value,\n      prizes: [...main.querySelectorAll('.tp')].map(i => Number(i.value)), played: Number($('#tpl').value) } } }), 'Tournament settings saved'); go();\n  };\n};\n\n/* ---------------- season pass ---------------- */\nRENDER.season = async main => {\n  const d = await api('/season'), st = d.settings;\n  const skinOpts = (sel, coins) => (coins ? '<option value=\"\">— coins —</option>' : '') + d.skins.map(k => '<option value=\"' + k.id + '\"' + (k.id === sel ? ' selected' : '') + '>' + esc(k.cat + ' · ' + k.id) + (k.pass ? ' ★' : '') + '</option>').join('');\n  const cell = (rw, track, i) => '<div class=\"row\" style=\"gap:6px\"><select class=\"rk\" data-t=\"' + track + '\" data-i=\"' + i + '\">' + skinOpts(rw.skin, track === 'free') + '</select><input type=\"number\" class=\"rc\" data-t=\"' + track + '\" data-i=\"' + i + '\" value=\"' + (rw.coins ?? '') + '\" placeholder=\"coins\" style=\"width:110px' + (rw.skin || track === 'prem' ? ';display:none' : '') + '\"></div>';\n  const max = Math.max(1, ...d.tiers);\n  main.innerHTML = '<h1>Season pass</h1><div class=\"sub\">Season ' + esc(d.season) + ' · ends ' + when(d.endsAt) + '</div>' +\n    '<div class=\"card row\" style=\"justify-content:space-between;margin-top:12px' + (st.enabled ? '' : ';border-color:var(--warn)') + '\"><label class=\"switch\"><input type=\"checkbox\" id=\"sen\"' + (st.enabled ? ' checked' : '') + '> <b>Season pass in the game</b></label>' +\n      '<span class=\"sub\">' + (st.enabled ? 'On: players earn season points, collect rewards and can buy premium.' : 'Off: hidden in the game; no points, rewards or premium sales. Players who already bought premium keep it (and no ads).') + '</span></div>' +\n    '<div class=\"grid\" style=\"margin-top:12px\">' +\n      '<div class=\"card kpi\"><div class=\"v\">' + num(d.players) + '</div><div class=\"l\">Players on the track</div></div>' +\n      '<div class=\"card kpi\"><div class=\"v\">' + num(d.premium) + '</div><div class=\"l\">With premium (' + (d.players ? Math.round(d.premium / d.players * 100) : 0) + '%)</div></div>' +\n      '<div class=\"card kpi\"><div class=\"v\">' + num(d.paidPlay) + '</div><div class=\"l\">Bought on Google Play (40 days)</div></div>' +\n    '</div>' +\n    '<h2>How far players got</h2><div class=\"card\"><svg class=\"chart\" viewBox=\"0 0 640 140\" style=\"max-height:200px\">' + d.tiers.map((n, i) => { const h = Math.round(n / max * 100), x = 12 + i * 20; return '<rect x=\"' + x + '\" y=\"' + (110 - h) + '\" width=\"15\" height=\"' + Math.max(1, h) + '\" rx=\"2\" fill=\"#c9a25a\"><title>Tier ' + i + ': ' + n + '</title></rect>' + (i % 5 === 0 ? '<text x=\"' + (x + 7) + '\" y=\"128\" fill=\"#b9a88a\" font-size=\"10\" text-anchor=\"middle\">' + i + '</text>' : ''); }).join('') + '</svg></div>' +\n    '<h2>Price</h2><div class=\"card\"><div class=\"form\"><label class=\"f\">Premium with coins<input id=\"sc\" type=\"number\" value=\"' + st.passCoins + '\"></label>' +\n      '<label class=\"f\">Premium price shown (EGP)<input id=\"se\" type=\"number\" value=\"' + st.passEgp + '\"></label></div>' +\n      '<div class=\"sub\" style=\"margin-top:8px\">The price players actually pay on Google Play is set in Play Console (product <span class=\"mono\">season_pass</span>); keep the two the same.</div></div>' +\n    '<h2>Rewards per tier</h2><div class=\"sub\">Free track: a skin or coins. Premium track: skins only (ads are removed only by the 199 EGP monthly no-ads plan). ★ = only from the season.</div>' +\n    '<div class=\"tablewrap\"><table><thead><tr><th>Tier</th><th>Free track</th><th>Premium track</th></tr></thead><tbody>' +\n      st.tiers.map((t, i) => '<tr class=\"tierrow\"><td><b>' + (i + 1) + '</b></td><td>' + cell(t.free, 'free', i) + '</td><td>' + cell(t.prem, 'prem', i) + '</td></tr>').join('') +\n    '</tbody></table></div><button class=\"btn gold\" id=\"ssv\" style=\"margin-top:12px\">Save the season pass</button>';\n  $('#sen').onchange = async e => {\n    const on = e.target.checked;\n    if (!confirm(on ? 'Show the season pass in the game again?' : 'Switch the season pass off? It disappears from the game for everyone.')) { e.target.checked = !on; return; }\n    await act(() => api('/settings', { method: 'PUT', body: { season: { enabled: on } } }), on ? 'Season pass is on' : 'Season pass is off'); go();\n  };\n  main.querySelectorAll('.rk').forEach(s => s.onchange = () => { const c = main.querySelector('.rc[data-t=\"' + s.dataset.t + '\"][data-i=\"' + s.dataset.i + '\"]'); c.style.display = s.value ? 'none' : ''; });\n  $('#ssv').onclick = async () => {\n    const tiers = st.tiers.map((_, i) => {\n      const one = tr => { const k = main.querySelector('.rk[data-t=\"' + tr + '\"][data-i=\"' + i + '\"]').value; return k ? { skin: k } : { coins: Number(main.querySelector('.rc[data-t=\"' + tr + '\"][data-i=\"' + i + '\"]').value) || 0 }; };\n      return { free: one('free'), prem: one('prem') };\n    });\n    await act(() => api('/settings', { method: 'PUT', body: { season: { passCoins: Number($('#sc').value), passEgp: Number($('#se').value), tiers } } }), 'Season pass saved'); go();\n  };\n};\n\n/* ---------------- titles ---------------- */\nconst GNAME = { domino: 'Dominoes', tawla: 'Backgammon', chess: 'Chess', ludo: 'Ludo', basra: 'Basra', tarneeb: 'Tarneeb', konkan: 'Konkan' };\nRENDER.titles = async main => {\n  const d = await api('/titles');\n  state.catalog.titles = d.list; state.catalog.icons = d.icons;\n  const cfg = d.settings;\n  const monthName = m => { const [y, mo] = m.split('-').map(Number); return new Date(Date.UTC(y, mo - 1, 15)).toLocaleString('en', { month: 'long', year: 'numeric' }); };\n  main.innerHTML = '<h1>Titles</h1><div class=\"sub\">A title shows under the player\\'s name: on their card, at their seat at the table and on the leaderboard. Players pick which of theirs to wear in Collection → Titles.</div>' +\n    '<h2>Player of the month</h2><div class=\"card\"><div class=\"form\">' +\n      '<label class=\"f\">Given by itself<span class=\"switch\"><input type=\"checkbox\" id=\"mo\"' + (cfg.monthly ? ' checked' : '') + '> on the 1st of each month</span></label>' +\n      '<label class=\"f\">Online games needed in the month<input id=\"mg\" type=\"number\" min=\"0\" value=\"' + cfg.minGames + '\"></label></div>' +\n      '<div class=\"sub\" style=\"margin:10px 0\">When a month ends, the player with the most points in each game (3 a win, 1 a game, online games only) gets that game\\'s title for the whole next month.</div>' +\n      '<button class=\"btn gold\" id=\"ms\">Save</button></div>' +\n    '<h2>The race this month · ' + esc(monthName(d.month)) + '</h2><div class=\"grid\" style=\"grid-template-columns:repeat(auto-fit,minmax(250px,1fr))\">' +\n      Object.entries(d.race).map(([g, rows]) => '<div class=\"card\"><div style=\"margin-bottom:8px\">' + badge(d.list.find(t => t.monthly === g), 'en') + '</div>' +\n        (rows.length ? '<table><tbody>' + rows.map((r, i) => '<tr><td>#' + (i + 1) + '</td><td><a href=\"#players/' + esc(r.id) + '\">' + esc(r.name) + '</a>' + (r.games < cfg.minGames ? ' <span class=\"muted\">(needs ' + (cfg.minGames - r.games) + ' more games)</span>' : '') + '</td><td class=\"num\">' + r.points + ' pts</td></tr>').join('') + '</tbody></table>' : '<div class=\"muted\">No games yet this month</div>') + '</div>').join('') + '</div>' +\n    (d.winners.length ? '<h2>Past winners</h2><table><thead><tr><th>Month</th>' + Object.keys(GNAME).map(g => '<th>' + GNAME[g] + '</th>').join('') + '</tr></thead><tbody>' +\n      d.winners.map(w => '<tr><td>' + esc(monthName(w.month)) + '</td>' + Object.keys(GNAME).map(g => { const x = w.rows.find(r => r.game === g); return '<td>' + (x ? '<a href=\"#players/' + esc(x.uid) + '\">' + esc(x.name) + '</a>' : '<span class=\"muted\">—</span>') + '</td>'; }).join('') + '</tr>').join('') + '</tbody></table>' : '') +\n    '<h2 class=\"row\" style=\"justify-content:space-between\">All titles (' + d.list.length + ')<button class=\"btn gold\" id=\"tn\">+ New title</button></h2>' +\n    '<div class=\"tgrid\">' + d.list.map(t => '<div class=\"card tcard\"><div class=\"pv\">' + badge(t, 'ar', true) + badge(t, 'en') + '</div>' +\n      '<div class=\"sub\">' + (t.monthly ? 'Given each month to the best ' + GNAME[t.monthly] + ' player · ' : '') + (d.counts[t.id] || 0) + ((d.counts[t.id] || 0) === 1 ? ' player has' : ' players have') + ' it now · effect: ' + esc(t.style.effect) + '</div>' +\n      '<div class=\"row\"><button class=\"btn sm\" data-edit=\"' + t.id + '\">Edit design</button>' + (t.monthly ? '' : '<button class=\"btn sm gold\" data-give=\"' + t.id + '\">Give to a player</button>') +\n      '<button class=\"btn sm\" data-hold=\"' + t.id + '\">Who has it</button>' + (t.monthly ? '' : '<button class=\"btn sm bad\" data-del=\"' + t.id + '\">Delete</button>') + '</div></div>').join('') + '</div>';\n  $('#ms').onclick = async () => { await act(() => api('/settings', { method: 'PUT', body: { titles: { monthly: $('#mo').checked, minGames: Number($('#mg').value) } } }), 'Saved'); go(); };\n  $('#tn').onclick = () => titleEditor(null);\n  main.querySelectorAll('[data-edit]').forEach(b => b.onclick = () => titleEditor(d.list.find(t => t.id === b.dataset.edit)));\n  main.querySelectorAll('[data-give]').forEach(b => b.onclick = () => titleGive(d.list.find(t => t.id === b.dataset.give)));\n  main.querySelectorAll('[data-hold]').forEach(b => b.onclick = () => titleHolders(d.list.find(t => t.id === b.dataset.hold)));\n  main.querySelectorAll('[data-del]').forEach(b => b.onclick = async () => { const t = d.list.find(x => x.id === b.dataset.del); if (confirm('Delete \"' + t.en + '\"? Everyone who has it loses it.')) { await act(() => api('/titles/' + t.id, { method: 'DELETE' }), 'Deleted'); go(); } });\n};\n\nfunction drawer() {\n  closeDrawer();\n  const sh = document.createElement('div'); sh.className = 'shade'; sh.onclick = closeDrawer;\n  const dr = document.createElement('div'); dr.className = 'drawer';\n  document.body.append(sh, dr);\n  return dr;\n}\n\nfunction titleEditor(t) {\n  const isNew = !t;\n  const cur = t ? structuredClone(t) : { id: '', ar: '', en: '', style: { bg: ['#f3cd62', '#b8862b'], fg: '#2a1a05', border: '#fff3c4', icon: 'crown', effect: 'shine' } };\n  const dr = drawer();\n  const icons = Object.keys(state.catalog.icons);\n  dr.innerHTML = '<button class=\"btn sm x\" id=\"cx\">Close ✕</button><h1>' + (isNew ? 'New title' : 'Edit title') + '</h1>' +\n    '<div class=\"card\" style=\"display:grid;gap:12px;justify-items:center;padding:26px;margin:14px 0;background:#0d0805\"><div id=\"pv1\"></div><div id=\"pv2\"></div><div class=\"sub\">Preview: what players see</div></div>' +\n    '<div class=\"form\">' +\n      (isNew ? '<label class=\"f\">Id (english letters, no spaces)<input id=\"ti\" placeholder=\"e.g. night_owl\" maxlength=\"32\"></label>' : '') +\n      '<label class=\"f\">Arabic name<input id=\"tar\" dir=\"rtl\" maxlength=\"30\" value=\"' + esc(cur.ar) + '\"></label>' +\n      '<label class=\"f\">English name<input id=\"ten\" maxlength=\"30\" value=\"' + esc(cur.en) + '\"></label>' +\n    '</div><h2>Design</h2><div class=\"form\">' +\n      '<label class=\"f\">Background (start)<input type=\"color\" id=\"b0\" value=\"' + cur.style.bg[0] + '\"></label>' +\n      '<label class=\"f\">Background (end)<input type=\"color\" id=\"b1\" value=\"' + cur.style.bg[1] + '\"></label>' +\n      '<label class=\"f\">Text and icon<input type=\"color\" id=\"fg\" value=\"' + cur.style.fg + '\"></label>' +\n      '<label class=\"f\">Border<input type=\"color\" id=\"bd\" value=\"' + cur.style.border + '\"></label>' +\n      '<label class=\"f\">Effect<select id=\"fx\">' + [['none', 'None'], ['shine', 'Shine: a light sweeps across'], ['glow', 'Glow: the border breathes'], ['pulse', 'Pulse: beats gently']].map(([k, l]) => '<option value=\"' + k + '\"' + (k === cur.style.effect ? ' selected' : '') + '>' + l + '</option>').join('') + '</select></label>' +\n    '</div><div class=\"sub\" style=\"margin:12px 0 6px\">Icon</div><div class=\"iconpick\">' + icons.map(k => '<button type=\"button\" data-ic=\"' + k + '\" title=\"' + k + '\" class=\"' + (k === cur.style.icon ? 'on' : '') + '\">' + (k === 'none' ? '∅' : iconSvg(k)) + '</button>').join('') + '</div>' +\n    '<div class=\"sub\" style=\"margin:14px 0 6px\">Quick looks</div><div class=\"row\" id=\"presets\"></div>' +\n    '<div class=\"row\" style=\"margin-top:18px\"><button class=\"btn gold\" id=\"tsv\">' + (isNew ? 'Create title' : 'Save') + '</button></div>';\n  const PRESETS = [['Gold', '#ffe08a', '#b8862b', '#2a1a05', '#fff6d6'], ['Emerald', '#11804f', '#063b25', '#ffd76a', '#ffd76a'], ['Royal', '#2c4bb0', '#0e1a4a', '#ffd76a', '#ffd76a'], ['Ruby', '#9c2430', '#4a0d14', '#ffd76a', '#ffd76a'],\n    ['Night', '#2b2b2b', '#0d0d0d', '#f3cd62', '#f3cd62'], ['Ice', '#18c3d6', '#0a5d8f', '#ffffff', '#c9f7ff'], ['Sunset', '#ff7a59', '#c2185b', '#ffffff', '#ffd1c2'], ['Wood', '#4a3526', '#1b120c', '#f4e6c8', '#c9a25a']];\n  $('#presets', dr).innerHTML = PRESETS.map((p, i) => '<button class=\"btn sm\" data-pre=\"' + i + '\" style=\"background:linear-gradient(90deg,' + p[1] + ',' + p[2] + ');color:' + p[3] + ';border-color:' + p[4] + '\">' + p[0] + '</button>').join('');\n  const read = () => ({ id: isNew ? $('#ti', dr).value.trim().toLowerCase() : cur.id, ar: $('#tar', dr).value, en: $('#ten', dr).value,\n    style: { bg: [$('#b0', dr).value, $('#b1', dr).value], fg: $('#fg', dr).value, border: $('#bd', dr).value, icon: cur.style.icon, effect: $('#fx', dr).value } });\n  const draw = () => { const v = read(); $('#pv1', dr).innerHTML = badge({ ...v, ar: v.ar || 'اسم اللقب' }, 'ar', true); $('#pv2', dr).innerHTML = badge({ ...v, en: v.en || 'Title name' }, 'en'); };\n  dr.querySelectorAll('input,select').forEach(i => i.oninput = draw);\n  dr.querySelectorAll('[data-ic]').forEach(b => b.onclick = () => { cur.style.icon = b.dataset.ic; dr.querySelectorAll('[data-ic]').forEach(x => x.classList.toggle('on', x === b)); draw(); });\n  dr.querySelectorAll('[data-pre]').forEach(b => b.onclick = () => { const p = PRESETS[b.dataset.pre]; $('#b0', dr).value = p[1]; $('#b1', dr).value = p[2]; $('#fg', dr).value = p[3]; $('#bd', dr).value = p[4]; draw(); });\n  $('#cx', dr).onclick = closeDrawer;\n  $('#tsv', dr).onclick = async () => {\n    const v = read();\n    if (!/^[a-z0-9_]{2,32}$/.test(v.id)) return toast('The id needs 2+ english letters, numbers or _', true);\n    if (!v.ar.trim() || !v.en.trim()) return toast('Write both names', true);\n    if (isNew && state.catalog.titles.some(t => t.id === v.id)) return toast('That id is taken', true);\n    await act(() => api('/titles', { method: 'PUT', body: v }), 'Saved · players see it at once'); closeDrawer(); go();\n  };\n  draw();\n}\n\nfunction titleGive(t, presetPlayer) {\n  const dr = drawer();\n  dr.innerHTML = '<button class=\"btn sm x\" id=\"cx\">Close ✕</button><h1>Give a title</h1><div style=\"margin:10px 0 16px\">' + badge(t, 'ar', true) + ' ' + badge(t, 'en') + '</div>' +\n    '<div class=\"form\"><label class=\"f\">For how long<select id=\"gd\"><option value=\"0\">For good</option><option value=\"7\">7 days</option><option value=\"30\">30 days</option><option value=\"90\">90 days</option><option value=\"365\">A year</option></select></label>' +\n    '<label class=\"f\">Note (only here)<input id=\"gn\" maxlength=\"100\" placeholder=\"why\"></label></div>' +\n    '<label class=\"switch\" style=\"margin:10px 0\"><input type=\"checkbox\" id=\"gp\" checked> Tell the player (push notification)</label>' +\n    '<form id=\"gs\" class=\"row\" style=\"margin:10px 0\"><input id=\"gq\" placeholder=\"Find a player: name, code, e-mail, phone\" style=\"flex:1\"><button class=\"btn\">Search</button></form><div id=\"gr\"></div>';\n  $('#cx', dr).onclick = closeDrawer;\n  const give = async (id, name) => {\n    if (!confirm('Give \"' + t.en + '\" to ' + name + '?')) return;\n    await act(() => api('/players/' + encodeURIComponent(id), { body: { action: 'title', title: t.id, days: Number($('#gd', dr).value), note: $('#gn', dr).value, notify: $('#gp', dr).checked } }), name + ' has the title now');\n  };\n  $('#gs', dr).onsubmit = async e => {\n    e.preventDefault();\n    const r = await api('/players?q=' + encodeURIComponent($('#gq', dr).value));\n    $('#gr', dr).innerHTML = r.rows.length ? '<table><tbody>' + r.rows.slice(0, 20).map(u => '<tr><td><b>' + esc(u.name) + '</b><div class=\"sub mono\">' + esc(u.code || u.id) + '</div></td><td>' + esc(u.contact) + '</td><td><button class=\"btn sm gold\" data-g=\"' + esc(u.id) + '\" data-n=\"' + esc(u.name) + '\">Give</button></td></tr>').join('') + '</tbody></table>' : '<div class=\"card empty\">Nobody found</div>';\n    $('#gr', dr).querySelectorAll('[data-g]').forEach(b => b.onclick = () => give(b.dataset.g, b.dataset.n));\n  };\n}\n\nasync function titleHolders(t) {\n  const dr = drawer();\n  const draw = async () => {\n    const r = await api('/titles/' + t.id + '/holders');\n    dr.innerHTML = '<button class=\"btn sm x\" id=\"cx\">Close ✕</button><h1>Who has it</h1><div style=\"margin:10px 0 16px\">' + badge(t, 'en', true) + '</div>' +\n      (r.rows.length ? '<table><thead><tr><th>Player</th><th>Since</th><th>Until</th><th>Note</th><th></th></tr></thead><tbody>' + r.rows.map(h => '<tr><td><a href=\"#players/' + esc(h.id) + '\">' + esc(h.name) + '</a></td><td>' + when(h.ts) + '</td><td>' + (h.until ? when(h.until) : 'for good') + '</td><td>' + esc(h.note || '') + '</td><td><button class=\"btn sm bad\" data-rm=\"' + esc(h.id) + '\">Take back</button></td></tr>').join('') + '</tbody></table>' : '<div class=\"card empty\">Nobody has it now</div>');\n    $('#cx', dr).onclick = closeDrawer;\n    dr.querySelectorAll('[data-rm]').forEach(b => b.onclick = async () => { await act(() => api('/players/' + encodeURIComponent(b.dataset.rm), { body: { action: 'untitle', title: t.id } }), 'Taken back'); draw(); });\n  };\n  await draw();\n}\n\n/* ---------------- events: Ramadan, Eid and others ---------------- */\nconst EKIND = { ramadan: 'Ramadan', eid: 'Eid', custom: 'Other' };\n// rough dates: check them against the moon sighting before the event\nconst EPRESETS = [\n  { id: 'ramadan_2027', kind: 'ramadan', ar: 'رمضان كريم', en: 'Ramadan Kareem', from: '2027-02-07T18:00', to: '2027-03-09T18:00', spMult: 2, missionMult: 1.5, titleId: 'ramadan_lantern', titleGames: 30 },\n  { id: 'eid_fitr_2027', kind: 'eid', ar: 'عيد الفطر', en: 'Eid al-Fitr', from: '2027-03-09T18:00', to: '2027-03-13T00:00', spMult: 2, missionMult: 2, titleId: 'eid_joy', titleGames: 10 },\n  { id: 'eid_adha_2027', kind: 'eid', ar: 'عيد الأضحى', en: 'Eid al-Adha', from: '2027-05-15T18:00', to: '2027-05-20T00:00', spMult: 2, missionMult: 2, titleId: 'eid_joy', titleGames: 10 },\n];\nconst toLocal = ms => { const d = new Date(ms + 3 * 3600_000); return d.toISOString().slice(0, 16); };      // Cairo (UTC+3) for the inputs\nconst fromLocal = s => Date.parse(s + ':00Z') - 3 * 3600_000;\nRENDER.events = async main => {\n  const d = await api('/events'), now = Date.now();\n  const status = e => e.from <= now && now < e.to ? '<span class=\"tag on\">on now</span>' : now < e.from ? '<span class=\"tag pending\">coming</span>' : '<span class=\"tag\">over</span>';\n  main.innerHTML = '<h1>Events</h1><div class=\"sub\">Ramadan, Eid or anything else. While an event is on: season points and mission coins can be multiplied, players who play enough online games get its title, and its limited skins are in the shop (only then). The game shows a banner with what\\'s on. Times are Cairo time.</div>' +\n    '<h2 class=\"row\" style=\"justify-content:space-between\">Events (' + d.events.length + ')<span class=\"row\">' + EPRESETS.map((p, i) => '<button class=\"btn sm\" data-pre=\"' + i + '\">+ ' + esc(p.en) + ' 2027</button>').join('') + '<button class=\"btn gold sm\" id=\"enew\">+ New event</button></span></h2>' +\n    (d.events.length ? '<table><thead><tr><th>Event</th><th>When (Cairo)</th><th>Season points</th><th>Mission coins</th><th>Title</th><th class=\"num\">Played</th><th></th></tr></thead><tbody>' +\n      d.events.map((e, i) => '<tr><td><b>' + esc(e.en) + '</b> · ' + esc(e.ar) + '<div class=\"sub\">' + EKIND[e.kind] + ' · ' + status(e) + '</div></td><td>' + when(e.from) + '<br>→ ' + when(e.to) + '</td><td>×' + e.spMult + '</td><td>×' + e.missionMult + '</td><td>' + (e.titleId ? badge(titleById(e.titleId), 'en') + '<div class=\"sub\">after ' + e.titleGames + ' games</div>' : '—') + '</td><td class=\"num\">' + num(e.stats.players) + ' players<div class=\"sub\">' + num(e.stats.games) + ' games</div></td>' +\n        '<td><div class=\"row\"><button class=\"btn sm\" data-edit=\"' + i + '\">Edit</button><button class=\"btn sm bad\" data-del=\"' + i + '\">Delete</button></div></td></tr>').join('') + '</tbody></table>' : '<div class=\"card empty\">No events yet. Add Ramadan with one click above.</div>') +\n    '<h2>Limited skins</h2><div class=\"card\"><div class=\"sub\" style=\"margin-bottom:8px\">On sale only while an event of their kind is on; players keep them after.</div>' +\n      ['ramadan', 'eid'].map(k => '<div style=\"margin:6px 0\"><b>' + EKIND[k] + ':</b> ' + d.limited.filter(s => s.event === k).map(s => '<span class=\"tag\" style=\"margin:2px\">' + esc(s.id) + ' · ' + short(s.price) + '</span>').join('') + '</div>').join('') + '</div>';\n  const save = async list => { await act(() => api('/settings', { method: 'PUT', body: { events: list } }), 'Saved · the game shows it at once'); closeDrawer(); go(); };\n  const editor = (ev, idx) => {\n    const dr = drawer();\n    const e = ev ? { ...ev } : { id: '', kind: 'custom', ar: '', en: '', from: now, to: now + 7 * 86_400_000, spMult: 2, missionMult: 1, titleId: '', titleGames: 10 };\n    dr.innerHTML = '<button class=\"btn sm x\" id=\"cx\">Close ✕</button><h1>' + (idx >= 0 ? 'Edit event' : 'New event') + '</h1><div class=\"form\" style=\"margin-top:12px\">' +\n      '<label class=\"f\">Id (english, no spaces)<input id=\"ei\" value=\"' + esc(e.id) + '\"' + (idx >= 0 ? ' disabled' : '') + '></label>' +\n      '<label class=\"f\">Kind<select id=\"ek\">' + Object.entries(EKIND).map(([k, l]) => '<option value=\"' + k + '\"' + (k === e.kind ? ' selected' : '') + '>' + l + '</option>').join('') + '</select></label>' +\n      '<label class=\"f\">Arabic name<input id=\"ea\" dir=\"rtl\" value=\"' + esc(e.ar) + '\"></label><label class=\"f\">English name<input id=\"ee\" value=\"' + esc(e.en) + '\"></label>' +\n      '<label class=\"f\">Starts (Cairo)<input id=\"ef\" type=\"datetime-local\" value=\"' + toLocal(e.from) + '\"></label><label class=\"f\">Ends (Cairo)<input id=\"et\" type=\"datetime-local\" value=\"' + toLocal(e.to) + '\"></label>' +\n      '<label class=\"f\">Season points ×<input id=\"es\" type=\"number\" step=\"0.5\" min=\"1\" max=\"5\" value=\"' + e.spMult + '\"></label><label class=\"f\">Mission coins ×<input id=\"em\" type=\"number\" step=\"0.5\" min=\"1\" max=\"5\" value=\"' + e.missionMult + '\"></label>' +\n      '<label class=\"f\">Title for taking part<select id=\"eti\"><option value=\"\">none</option>' + d.titles.map(t => '<option value=\"' + t.id + '\"' + (t.id === e.titleId ? ' selected' : '') + '>' + esc(t.en + ' · ' + t.ar) + '</option>').join('') + '</select></label>' +\n      '<label class=\"f\">…after this many online games<input id=\"eg\" type=\"number\" min=\"0\" value=\"' + e.titleGames + '\"></label>' +\n      '</div><div class=\"sub\" style=\"margin-top:10px\">Ramadan and Eid dates move with the moon: check them before the event.</div><button class=\"btn gold\" id=\"esv\" style=\"margin-top:14px\">Save event</button>';\n    $('#cx', dr).onclick = closeDrawer;\n    $('#esv', dr).onclick = () => {\n      const v = { id: $('#ei', dr).value.trim().toLowerCase(), kind: $('#ek', dr).value, ar: $('#ea', dr).value, en: $('#ee', dr).value, from: fromLocal($('#ef', dr).value), to: fromLocal($('#et', dr).value),\n        spMult: Number($('#es', dr).value), missionMult: Number($('#em', dr).value), titleId: $('#eti', dr).value, titleGames: Number($('#eg', dr).value) };\n      if (!/^[a-z0-9_]{2,32}$/.test(v.id)) return toast('The id needs 2+ english letters, numbers or _', true);\n      if (!v.ar.trim() || !v.en.trim()) return toast('Write both names', true);\n      if (!(v.to > v.from)) return toast('The end must be after the start', true);\n      const list = d.events.map(({ stats, ...x }) => x);\n      if (idx >= 0) list[idx] = v; else { if (list.some(x => x.id === v.id)) return toast('That id is taken', true); list.push(v); }\n      save(list);\n    };\n  };\n  $('#enew').onclick = () => editor(null, -1);\n  main.querySelectorAll('[data-pre]').forEach(b => b.onclick = () => { const p = EPRESETS[b.dataset.pre]; editor({ ...p, from: fromLocal(p.from), to: fromLocal(p.to) }, -1); });\n  main.querySelectorAll('[data-edit]').forEach(b => b.onclick = () => editor(d.events[b.dataset.edit], Number(b.dataset.edit)));\n  main.querySelectorAll('[data-del]').forEach(b => b.onclick = () => { const e = d.events[b.dataset.del]; if (confirm('Delete \"' + e.en + '\"?')) save(d.events.filter((_, i) => i !== Number(b.dataset.del)).map(({ stats, ...x }) => x)); });\n};\n\n/* ---------------- settings pages: one form engine ----------------\n * A page is a list of sections; each field points at a setting by its path ('economy.startCoins'). Changed fields\n * light up, a bar at the bottom counts them and saves only what changed; leaving with changes asks first. */\nconst getAt = (o, p) => p.split('.').reduce((a, k) => a == null ? a : a[k], o);\nconst setAt = (o, p, v) => { const ks = p.split('.'); let a = o; ks.slice(0, -1).forEach(k => { a[k] = a[k] ?? {}; a = a[k]; }); a[ks[ks.length - 1]] = v; };\nconst exact = n => { const a = Math.abs(n), t = (x, d) => String(+x.toFixed(d)); return a >= 1e6 ? t(n / 1e6, 3) + 'M' : a >= 1e3 ? t(n / 1e3, 2) + 'K' : String(n); };\nconst coinsHint = v => { const n = Number(v); return Number.isFinite(n) && n ? '= ' + exact(n) + ' coins' : ''; };\nfunction fieldHtml(f, v) {\n  const id = 'f_' + f.path.replace(/\\W/g, '_');\n  const head = '<span class=\"l\">' + esc(f.label) + '</span>';\n  const help = f.help ? '<span class=\"h\">' + f.help + '</span>' : '';\n  const numIn = (val, extra) => '<input type=\"number\" data-num value=\"' + esc(val) + '\"' + (f.min !== undefined ? ' min=\"' + f.min + '\"' : '') + (f.max !== undefined ? ' max=\"' + f.max + '\"' : '') + (f.step ? ' step=\"' + f.step + '\"' : '') + (extra || '') + '>';\n  if (f.type === 'bool') return '<div class=\"fld\" data-path=\"' + f.path + '\" data-type=\"bool\">' + head + '<label class=\"switch\"><input type=\"checkbox\"' + (v ? ' checked' : '') + '> ' + esc(f.on || 'On') + '</label>' + help + '</div>';\n  if (f.type === 'text') return '<div class=\"fld\" data-path=\"' + f.path + '\" data-type=\"text\"' + (f.wide ? ' style=\"grid-column:1/-1\"' : '') + '>' + head + '<input type=\"text\" value=\"' + esc(v) + '\" maxlength=\"' + (f.maxlen || 300) + '\"' + (f.rtl ? ' dir=\"auto\"' : '') + '>' + help + '</div>';\n  if (f.type === 'select') return '<div class=\"fld\" data-path=\"' + f.path + '\" data-type=\"select\">' + head + '<select>' + f.options.map(([k, l]) => '<option value=\"' + esc(k) + '\"' + (String(k) === String(v) ? ' selected' : '') + '>' + esc(l) + '</option>').join('') + '</select>' + help + '</div>';\n  if (f.type === 'list') {\n    const arr = v || [];\n    const item = (x, i) => '<div class=\"it\"><b>' + esc(f.itemLabel ? f.itemLabel(i) : '#' + (i + 1)) + '</b>' + numIn(x) + (f.fixed ? '<span></span>' : '<button type=\"button\" class=\"xbtn\" data-rm title=\"Remove\">✕</button>') + (f.coins ? '<span class=\"hint\"></span>' : '') + '</div>';\n    return '<div class=\"fld\" data-path=\"' + f.path + '\" data-type=\"list\"' + (f.coins ? ' data-coins' : '') + ' style=\"grid-column:1/-1\">' + head + help + '<div class=\"lst' + (arr.length > 3 ? ' wide' : '') + '\">' + arr.map(item).join('') + '</div>' +\n      (f.fixed ? '' : '<div><button type=\"button\" class=\"btn sm\" data-add' + (f.maxItems && arr.length >= f.maxItems ? ' disabled' : '') + '>+ Add</button></div>') + '</div>';\n  }\n  // numbers: coins (with a 1.5M preview), seconds, percent, plain\n  return '<div class=\"fld\" data-path=\"' + f.path + '\" data-type=\"num\"' + (f.type === 'coins' ? ' data-coins' : '') + '>' + head + numIn(v) + (f.type === 'coins' ? '<span class=\"hint\"></span>' : '') + help + '</div>';\n}\nfunction readField(el) {\n  const t = el.dataset.type;\n  if (t === 'bool') return el.querySelector('input').checked;\n  if (t === 'text') return el.querySelector('input').value;\n  if (t === 'select') { const v = el.querySelector('select').value; return /^-?\\d+$/.test(v) ? Number(v) : v; }\n  if (t === 'list') return [...el.querySelectorAll('.lst input')].map(i => Number(i.value));\n  return Number(el.querySelector('input').value);\n}\n/** Draws a settings page into `main` and wires the save bar. `extra(main, values, changed)` adds custom parts. */\nasync function settingsPage(main, title, lead, sections, opts = {}) {\n  const s = await api('/settings');\n  const orig = structuredClone(s);\n  main.innerHTML = '<h1>' + esc(title) + '</h1><div class=\"lead\">' + lead + '</div>' +\n    sections.map(sec => '<div class=\"sec\"><h2>' + esc(sec.title) + '</h2>' + (sec.help ? '<div class=\"help\">' + sec.help + '</div>' : '') +\n      '<div class=\"card\">' + (sec.html ? sec.html(s) : '') + (sec.fields && sec.fields.length ? '<div class=\"fgrid\">' + sec.fields.map(f => fieldHtml(f, getAt(s, f.path))).join('') + '</div>' : '') + (sec.after ? sec.after(s) : '') + '</div></div>').join('') +\n    (opts.footer ? opts.footer(s) : '') +\n    '<div class=\"savebar\" id=\"sbar\" hidden><span><span class=\"msg\" id=\"smsg\"></span> <span class=\"sub\" id=\"sdet\"></span></span><span class=\"row\"><button class=\"btn\" id=\"sdis\">Discard</button><button class=\"btn gold\" id=\"ssave\">Save changes</button></span></div>';\n  const fields = [...main.querySelectorAll('.fld[data-path]')];\n  const custom = opts.collect || (() => ({}));   // pages with their own controls add their values here\n  const current = () => { const v = structuredClone(orig); fields.forEach(el => setAt(v, el.dataset.path, readField(el))); Object.entries(custom()).forEach(([p, x]) => setAt(v, p, x)); return v; };\n  const changedPaths = () => {\n    const v = current(), out = [];\n    fields.forEach(el => { if (JSON.stringify(getAt(v, el.dataset.path)) !== JSON.stringify(getAt(orig, el.dataset.path))) out.push(el.dataset.path); });\n    Object.keys(custom()).forEach(p => { if (JSON.stringify(getAt(v, p)) !== JSON.stringify(getAt(orig, p))) out.push(p); });\n    return out;\n  };\n  const labelOf = p => { const el = fields.find(x => x.dataset.path === p); return el ? el.querySelector('.l').textContent : (opts.labels || {})[p] || p; };\n  const refresh = () => {\n    main.querySelectorAll('.fld[data-coins]').forEach(el => {\n      if (el.dataset.type === 'list') el.querySelectorAll('.it').forEach(it => { const h = it.querySelector('.hint'); if (h) h.textContent = coinsHint(it.querySelector('input').value); });\n      else el.querySelector('.hint').textContent = coinsHint(el.querySelector('input').value);\n    });\n    const ch = changedPaths();\n    fields.forEach(el => el.classList.toggle('changed', ch.includes(el.dataset.path)));\n    $('#sbar').hidden = !ch.length;\n    $('#smsg').textContent = ch.length === 1 ? '1 unsaved change' : ch.length + ' unsaved changes';\n    $('#sdet').textContent = ch.slice(0, 4).map(labelOf).join(' · ') + (ch.length > 4 ? ' …' : '');\n    if (opts.onChange) opts.onChange(current());\n  };\n  main.addEventListener('input', refresh); main.addEventListener('change', refresh);\n  main.querySelectorAll('.fld[data-type=list]').forEach(el => {\n    const f = sections.flatMap(x => x.fields || []).find(x => x.path === el.dataset.path);\n    el.addEventListener('click', e => {\n      if (e.target.matches('[data-rm]')) { if (el.querySelectorAll('.it').length > (f.minItems || 1)) e.target.closest('.it').remove(); renumber(); refresh(); }\n      if (e.target.matches('[data-add]')) {\n        const items = el.querySelectorAll('.it'), last = items[items.length - 1];\n        const it = last.cloneNode(true); it.querySelector('input').value = f.addValue ? f.addValue([...items].map(i => Number(i.querySelector('input').value))) : last.querySelector('input').value;\n        el.querySelector('.lst').appendChild(it); renumber(); refresh();\n      }\n    });\n    const renumber = () => { const its = el.querySelectorAll('.it'); its.forEach((it, i) => it.querySelector('b').textContent = f.itemLabel ? f.itemLabel(i) : '#' + (i + 1)); const add = el.querySelector('[data-add]'); if (add) add.disabled = !!(f.maxItems && its.length >= f.maxItems); };\n  });\n  dirtyCheck = () => changedPaths().length > 0;\n  $('#sdis').onclick = () => go.call(null, dirtyCheck = null);\n  $('#ssave').onclick = async () => {\n    const v = current(), ch = changedPaths(), body = {};\n    if (opts.confirm) { const q = opts.confirm(v, orig, ch); if (q && !confirm(q)) return; }\n    ch.forEach(p => setAt(body, p, getAt(v, p)));\n    const saved = await act(() => api('/settings', { method: 'PUT', body }), 'Saved · the game uses it now');\n    dirtyCheck = null;\n    // the server checks every value: show what it kept (a value out of range comes back corrected)\n    const fixed = ch.filter(p => JSON.stringify(getAt(saved, p)) !== JSON.stringify(getAt(v, p)));\n    if (fixed.length) toast('Adjusted to the allowed range: ' + fixed.map(labelOf).join(', '), true);\n    go();\n  };\n  refresh();\n  if (opts.after) opts.after(main, s);\n}\n\n/* ---------------- games & ads ---------------- */\nRENDER.games = async main => {\n  const GKEYS = Object.keys(GNAME);\n  let off = [], origOff = [];\n  await settingsPage(main, 'Games & ads', 'Which games are open, how often the full-screen ad shows between games, the coins for watching ads, and the time limits for a move. Changes reach players who are online at once.', [\n    { title: 'Games', help: 'A game switched off disappears from online play and practice: players who tap it see “This game is closed for a while”. Games already being played finish normally. Use it if a game has a problem.',\n      html: s => { off = [...s.games.off]; origOff = [...s.games.off]; return '<div class=\"toggles\">' + GKEYS.map(g => '<label class=\"tog' + (off.includes(g) ? ' off' : '') + '\" data-g=\"' + g + '\"><span><b>' + GNAME[g] + '</b><div class=\"sub\">' + (off.includes(g) ? 'Off' : 'Open') + '</div></span><span class=\"switch\"><input type=\"checkbox\"' + (off.includes(g) ? '' : ' checked') + '></span></label>').join('') + '</div>'; } },\n    { title: 'Ads between games', help: 'The full-screen ad after a game, finished or left. Players on the ad-free plan never see it.',\n      fields: [{ path: 'ads.every', type: 'select', label: 'Show the ad', options: [[0, 'Never'], [1, 'After every game'], [2, 'After 1 game in 2'], [3, 'After 1 game in 3'], [4, 'After 1 game in 4'], [5, 'After 1 game in 5']] }],\n      after: s => '<div class=\"sub\" style=\"margin-top:10px\">What a player sees, game after game:</div><div class=\"adrow\" id=\"adrow\"></div>' },\n    { title: 'Ads for coins (the player chooses)', fields: [\n      { path: 'economy.adReward', type: 'coins', label: 'Coins for watching an ad', min: 0 },\n      { path: 'economy.adsPerDay', type: 'int', label: 'Ads for coins a day', min: 0, max: 100 },\n      { path: 'economy.skinAdsPerDay', type: 'int', label: 'Ads a day towards a skin', min: 0, max: 500, help: 'Skins unlocked by ads take 30–150 ads.' },\n      { path: 'economy.doubleMax', type: 'coins', label: '“Double your winnings” up to', min: 0, help: 'After a win, an ad pays the winnings again, up to this.' }] },\n    { title: 'Time limits', fields: [\n      { path: 'play.dominoTurnSeconds', type: 'int', label: 'Seconds for a move: dominoes', min: 5, max: 60 },\n      { path: 'play.turnSeconds', type: 'int', label: 'Seconds for a move: tawla, ludo and card games', min: 5, max: 60 },\n      { path: 'play.botFillSeconds', type: 'int', label: 'Seconds before the computer fills empty seats', min: 2, max: 120, help: 'When not enough people join a quick game.' }] },\n  ], {\n    collect: () => { const o = GKEYS.filter(g => off.includes(g)); return { 'games.off': o.length === origOff.length && o.every(g => origOff.includes(g)) ? origOff : o }; },\n    labels: { 'games.off': 'Games on/off' },\n    confirm: (v, o) => { const newly = v.games.off.filter(g => !o.games.off.includes(g)); return newly.length ? 'Switch off ' + newly.map(g => GNAME[g]).join(', ') + '? Players can\\'t start new games of it until you switch it back on.' : null; },\n    onChange: v => { const n = v.ads.every; const r = $('#adrow'); if (r) r.innerHTML = Array.from({ length: 8 }, (_, i) => '<span class=\"' + (n && i % n === 0 ? 'ad' : '') + '\">Game ' + (i + 1) + ': ' + (n && i % n === 0 ? 'ad' : 'no ad') + '</span>').join(''); },\n    after: main => main.querySelectorAll('.tog').forEach(t => t.querySelector('input').onchange = e => {\n      const g = t.dataset.g; off = e.target.checked ? off.filter(x => x !== g) : [...off, g];\n      t.classList.toggle('off', !e.target.checked); t.querySelector('.sub').textContent = e.target.checked ? 'Open' : 'Off';\n    }),\n  });\n};\n\n/* ---------------- economy ---------------- */\nRENDER.economy = async main => {\n  await settingsPage(main, 'Economy', 'Every coin that comes into the game and goes out of it. Coins can\\'t be bought: players get them from playing, daily rewards, the wheel, missions and ads.', [\n    { title: 'New players and coming back', fields: [\n      { path: 'economy.startCoins', type: 'coins', label: 'Coins for a new player', min: 0 },\n      { path: 'economy.tutorialCoins', type: 'coins', label: 'Coins for finishing the first-game guide', min: 0 },\n      { path: 'economy.comebackCoins', type: 'coins', label: 'Gift for coming back', min: 0 },\n      { path: 'economy.comebackDays', type: 'int', label: '…after this many days away', min: 0, max: 60, help: '0 switches the gift off. Players also get one reminder push then.' },\n      { path: 'economy.referralBonus', type: 'coins', label: 'Inviting a friend', min: 0, help: 'Paid to both after the friend\\'s first game (up to 20 friends each).' }] },\n    { title: 'Daily reward', help: 'Grows for each day in a row the player comes back. Day 7 repeats after.', fields: [\n      { path: 'economy.streak', type: 'list', coins: true, fixed: true, label: 'Coins by day', itemLabel: i => 'Day ' + (i + 1) }] },\n    { title: 'Tables: stakes and the house fee', help: 'The stakes are the choices players get before a game (smallest first). The house keeps its fee from what the winners take.', fields: [\n      { path: 'economy.stakes', type: 'list', coins: true, label: 'Stakes', itemLabel: i => 'Stake ' + (i + 1), minItems: 1, maxItems: 10, addValue: a => Math.max(...a) * 2 },\n      { path: 'economy.houseFeePct', type: 'int', label: 'House fee (%)', min: 0, max: 50 }],\n      after: () => '<div class=\"sub\" id=\"feeex\" style=\"margin-top:10px\"></div>' },\n    { title: 'Lucky wheel', help: 'One free spin a day, then spins unlocked by ads. The 8 prizes in the order they sit on the wheel; the big ones come up rarely.', fields: [\n      { path: 'economy.wheelCoins', type: 'list', coins: true, fixed: true, label: 'Prizes', itemLabel: i => 'Slice ' + (i + 1) },\n      { path: 'economy.wheelMaxSpins', type: 'int', label: 'Spins a day (most)', min: 1, max: 50 }] },\n    { title: 'Weekly missions chest', help: 'Opens after 3, 8 and 15 missions done in the week.', fields: [\n      { path: 'economy.chestCoins', type: 'list', coins: true, fixed: true, label: 'Coins', itemLabel: i => ['3 done', '8 done', '15 done'][i] }] },\n    { title: 'What a game is worth', help: 'Experience (levels), season points (the season pass: 100 a tier) and league points (the monthly leagues). Online games; games against the computer count less.', fields: [\n      { path: 'progress.xpWin', type: 'int', label: 'XP for a win', min: 0 }, { path: 'progress.xpLoss', type: 'int', label: 'XP for a loss', min: 0 },\n      { path: 'progress.spWin', type: 'int', label: 'Season points for a win', min: 0 }, { path: 'progress.spLoss', type: 'int', label: 'Season points for a loss', min: 0 },\n      { path: 'progress.spDaily', type: 'int', label: 'Season points for the daily reward', min: 0 },\n      { path: 'progress.lpWin', type: 'int', label: 'League points for a win', min: 0 }, { path: 'progress.lpLoss', type: 'int', label: 'League points for a loss', max: 0, help: 'Negative: taken away.' }] },\n  ], {\n    onChange: v => { const e = $('#feeex'); if (!e) return; const st = v.economy.stakes[1] ?? v.economy.stakes[0], fee = Math.floor(st * v.economy.houseFeePct / 100);\n      e.innerHTML = 'Example: 1 vs 1 at <b>' + short(st) + '</b>: the winner gets their stake back + <b>' + short(st - fee) + '</b>, the game keeps <b>' + short(fee) + '</b>, the loser loses ' + short(st) + '.'; },\n    confirm: (v, o) => v.economy.startCoins > o.economy.startCoins * 5 ? 'New players would start with ' + short(v.economy.startCoins) + ' coins. Sure?' : null,\n  });\n};\n\n/* ---------------- coin prizes ---------------- */\nRENDER.coinprizes = async main => {\n  const h = await api('/prizehistory');\n  const KIND = { weekly: 'Weekly #1', monthly: 'Top earner of the month', gov: 'Governorate of the week', tourney: 'Tournament' };\n  await settingsPage(main, 'Prizes', 'The coin prizes paid by the game itself. Tournament prizes are on the <a href=\"#tourney\">Tournaments</a> page; event titles on <a href=\"#events\">Events</a>.', [\n    { title: 'Weekly leaderboard', help: 'Paid every Monday to the best of the week (3 points a win, 1 a game, online games). Add places to pay 2nd, 3rd…', fields: [\n      { path: 'economy.weeklyPrizes', type: 'list', coins: true, label: 'Prize by place', itemLabel: i => '#' + (i + 1), minItems: 1, maxItems: 10, addValue: a => Math.round(a[a.length - 1] / 2) }] },\n    { title: 'Top earners of the month', help: 'On the 1st of each month: the players who won the most coins in games last month, all games together.', fields: [\n      { path: 'economy.monthlyPrizes', type: 'list', coins: true, label: 'Prize by place', itemLabel: i => '#' + (i + 1), minItems: 1, maxItems: 10, addValue: a => Math.round(a[a.length - 1] / 2) }] },\n    { title: 'Governorate of the week', help: 'The governorate whose players scored most in the week: each of its players who played enough gets the prize.', fields: [\n      { path: 'economy.govPrize', type: 'coins', label: 'Prize for each player', min: 0 },\n      { path: 'economy.govMinGames', type: 'int', label: 'Games needed in the week', min: 0 },\n      { path: 'economy.govTop', type: 'int', label: 'Best players counted per governorate', min: 1, help: 'Only a governorate\\'s best this many add to its score.' }] },\n  ], {\n    footer: () => '<div class=\"sec\"><h2>Paid lately</h2>' + (h.rows.length ? '<div class=\"tablewrap\"><table><thead><tr><th>When</th><th>Prize</th><th>Player</th><th class=\"num\">Coins</th></tr></thead><tbody>' +\n      h.rows.map(r => '<tr><td>' + when(r.ts) + '</td><td>' + esc(KIND[r.kind] || r.kind) + '</td><td><a href=\"#players/' + esc(r.id) + '\">' + esc(r.name || r.id) + '</a></td><td class=\"num\">' + num(r.coins) + '</td></tr>').join('') + '</tbody></table></div>' : '<div class=\"card empty\">No prizes paid yet</div>') + '</div>',\n  });\n};\n\n/* ---------------- system ---------------- */\nRENDER.system = async main => {\n  await settingsPage(main, 'System', 'Switches for the whole game. Every change is in the <a href=\"#log\">activity log</a>.', [\n    { title: 'Maintenance', help: 'While on, no new games start (games already on finish) and players see the message when they open the game.', fields: [\n      { path: 'maintenance.on', type: 'bool', label: 'Maintenance mode', on: 'On: no new games' },\n      { path: 'maintenance.message', type: 'text', label: 'Message players see', wide: true, rtl: true, maxlen: 300 }] },\n    { title: 'Forced update', help: 'Phones from Google Play update by themselves as soon as Play has a newer version. Set this only to stop an old version at once: apps with a lower build number get an update screen they can\\'t close and can\\'t start games. The build number is the AAB\\'s version code (board-battles-<b>125</b>.aab). Raise it only once that version is live on Play.', fields: [\n      { path: 'update.minBuild', type: 'int', label: 'Oldest app build allowed (0: any)', min: 0 }] },\n    { title: 'Money prizes (Vodafone Cash)', help: 'The old monthly money prize for each game\\'s best player. Off: the game gives coin prizes only.', fields: [\n      { path: 'prizes.enabled', type: 'bool', label: 'Money prizes', on: 'On' },\n      { path: 'prizes.egp', type: 'int', label: 'EGP for each game\\'s winner', min: 0 },\n      { path: 'titles.minGames', type: 'int', label: 'Online games needed in the month (also for “player of the month”)', min: 0 }] },\n  ], {\n    confirm: (v, o) => v.maintenance.on && !o.maintenance.on ? 'Switch maintenance on? No new games start until you switch it off.' : v.prizes.enabled && !o.prizes.enabled ? 'Switch money prizes on? Winners will ask you to pay them on Vodafone Cash.' : null,\n    footer: () => '<div class=\"sec\"><h2>Back to the defaults</h2><div class=\"card row\" style=\"justify-content:space-between\"><span class=\"sub\">Every setting on every page back to what the game shipped with (events and titles stay).</span><button class=\"btn bad\" id=\"rs\">Reset all settings</button></div></div>',\n    after: () => { $('#rs').onclick = async () => { if (prompt('Type RESET to put every setting back to the defaults') === 'RESET') { await act(() => api('/settings/reset', { body: {} }), 'Back to the defaults'); dirtyCheck = null; go(); } }; },\n  });\n};\n\n/* ---------------- live tables ---------------- */\nRENDER.live = async main => {\n  const MODE = m => { const g = Object.keys(GNAME).find(k => m.startsWith(k)) || (m.startsWith('ffa') || m === 'team' ? 'domino' : m.startsWith('chess') ? 'chess' : ''); return (GNAME[g] || '') + ' · ' + m; };\n  const draw = async () => {\n    const d = await api('/live');\n    if (state.view !== 'live') return;\n    const people = d.tables.filter(t => t.seats.some(x => x && !x.bot));\n    main.innerHTML = '<h1>Live tables</h1><div class=\"lead\">Refreshes every 5 seconds · ' + num(d.online.length) + ' online · ' + num(d.tables.length) + ' tables (' + num(people.length) + ' with people)' + (d.queued.length ? ' · waiting for a game: ' + d.queued.map(q => esc(q.key) + ' (' + q.players + ')').join(', ') : '') + '</div>' +\n      '<div class=\"tabs\" id=\"lf\"><button data-f=\"people\" class=\"' + (state.liveAll ? '' : 'on') + '\">With people</button><button data-f=\"all\" class=\"' + (state.liveAll ? 'on' : '') + '\">All tables</button></div>' +\n      ((state.liveAll ? d.tables : people).length ? '<div class=\"livegrid\">' + (state.liveAll ? d.tables : people).map(t => '<div class=\"lt\"><div class=\"top\"><b>' + esc(MODE(t.mode)) + '</b><span class=\"tag ' + (t.phase === 'play' || t.phase === 'rend' ? 'on' : '') + '\">' + esc(t.phase) + '</span></div>' +\n        '<div class=\"sub\" style=\"margin-bottom:6px\">' + (t.stake ? 'stake ' + short(t.stake) : t.seats.filter(x => x && !x.bot).length === 1 ? 'practice vs the computer' : 'friendly, no stake') + (t.private && t.seats.filter(x => x && !x.bot).length > 1 ? ' · private room ' + esc(t.code || '') : '') + '</div>' +\n        t.seats.map(x => x ? '<div class=\"seat\"><span><span class=\"dot' + (x.online || x.bot ? '' : ' off') + '\"></span>' + (x.bot ? '<span class=\"muted\">' + esc(x.name) + ' (computer)</span>' : '<a href=\"#players/' + esc(x.uid) + '\" data-p=\"' + esc(x.uid) + '\">' + esc(x.name) + '</a>') + '</span></div>' : '<div class=\"seat muted\">empty seat</div>').join('') + '</div>').join('') + '</div>'\n        : '<div class=\"card empty\">No tables right now</div>') +\n      '<h2>Online now (' + d.online.length + ')</h2>' + (d.online.length ? '<div class=\"tablewrap\"><table><thead><tr><th>Player</th><th class=\"num\">Coins</th><th>Where</th><th></th></tr></thead><tbody>' +\n        d.online.sort((a, b) => (b.table ? 1 : 0) - (a.table ? 1 : 0)).map(u => '<tr><td><a href=\"#players/' + esc(u.uid) + '\" data-p=\"' + esc(u.uid) + '\">' + esc(u.name) + '</a></td><td class=\"num\">' + short(u.coins) + '</td><td>' + (u.mode ? esc(MODE(u.mode)) : '<span class=\"muted\">in the café</span>') + '</td>' +\n        '<td><button class=\"btn sm\" data-kick=\"' + esc(u.uid) + '\" data-n=\"' + esc(u.name) + '\" title=\"Closes their connection; the app reconnects by itself\">Reconnect</button></td></tr>').join('') + '</tbody></table></div>' : '<div class=\"card empty\">Nobody online</div>');\n    main.querySelectorAll('[data-f]').forEach(b => b.onclick = () => { state.liveAll = b.dataset.f === 'all'; draw(); });\n    main.querySelectorAll('[data-p]').forEach(a => a.onclick = e => { e.preventDefault(); openPlayer(a.dataset.p); });\n    main.querySelectorAll('[data-kick]').forEach(b => b.onclick = async () => { if (confirm('Disconnect ' + b.dataset.n + '? Their app reconnects by itself (it helps when a player is stuck).')) { await act(() => api('/players/' + encodeURIComponent(b.dataset.kick), { body: { action: 'kick' } }), 'Disconnected'); draw(); } });\n  };\n  await draw();\n  liveTimer = setInterval(() => { if (!document.querySelector('.drawer')) draw().catch(() => {}); }, 5000);\n};\n\n/* ---------------- reports and support ---------------- */\nRENDER.reports = async main => {\n  const [r, s] = await Promise.all([api('/reports'), api('/support')]);\n  main.innerHTML = '<h1>Reports & support</h1>' +\n    '<h2>Player reports (' + r.rows.length + ')</h2>' + (r.rows.length ? '<div class=\"tablewrap\"><table><thead><tr><th>When</th><th>About</th><th>Reason</th><th>By</th><th></th></tr></thead><tbody>' +\n      r.rows.map(x => '<tr><td>' + when(x.ts) + '</td><td><a href=\"#players/' + esc(x.about_id) + '\">' + esc(x.about_name || x.about_id) + '</a>' + (x.banned ? ' <span class=\"tag banned\">banned</span>' : x.muted_until > Date.now() ? ' <span class=\"tag\">muted</span>' : '') + '</td><td>' + esc(x.reason) + '</td><td>' + esc(x.from_name || x.from_id) + '</td><td><a class=\"btn sm\" href=\"#players/' + esc(x.about_id) + '\">Open</a></td></tr>').join('') +\n      '</tbody></table></div>' : '<div class=\"card empty\">No reports</div>') +\n    '<h2>Support messages (' + s.rows.length + ')</h2>' + (s.rows.length ? s.rows.map(x => '<div class=\"card\" style=\"margin-bottom:8px\"><div class=\"sub\">#' + x.id + ' · ' + when(x.ts) + ' · ' + esc(x.name || 'player') + (x.contact ? ' · <span class=\"mono\">' + esc(x.contact) + '</span>' : '') + ' · ' + esc(x.app || '') + (x.user_id ? ' · <a href=\"#players/' + esc(x.user_id) + '\">player</a>' : '') + '</div><div style=\"white-space:pre-wrap;margin-top:6px\">' + esc(x.text) + '</div></div>').join('') : '<div class=\"card empty\">No messages</div>');\n};\n\n/* ---------------- purchases ---------------- */\nRENDER.purchases = async main => {\n  const d = await api('/purchases');\n  const byProduct = {}; d.rows.forEach(p => byProduct[p.product] = (byProduct[p.product] || 0) + 1);\n  main.innerHTML = '<h1>Purchases</h1><div class=\"sub\">Google Play purchases checked and credited by the server (the latest 300)</div>' +\n    '<div class=\"flags\">' + Object.entries(byProduct).map(([k, v]) => '<span class=\"flag\">' + esc(k) + ': ' + v + '</span>').join('') + '</div>' +\n    (d.rows.length ? '<div class=\"tablewrap\"><table><thead><tr><th>When</th><th>Player</th><th>Product</th><th class=\"num\">Coins</th><th>Order</th></tr></thead><tbody>' +\n      d.rows.map(p => '<tr><td>' + when(p.ts) + '</td><td><a href=\"#players/' + esc(p.user_id) + '\">' + esc(p.name || p.user_id) + '</a></td><td>' + esc(p.product) + '</td><td class=\"num\">' + (p.coins ? num(p.coins) : '') + '</td><td class=\"mono\">' + esc(p.order_id || '') + '</td></tr>').join('') +\n      '</tbody></table></div>' : '<div class=\"card empty\">No purchases yet</div>');\n};\n\n/* ---------------- activity log ---------------- */\nRENDER.log = async main => {\n  const d = await api('/log');\n  main.innerHTML = '<h1>Activity log</h1><div class=\"sub\">What was done from this dashboard</div>' +\n    (d.rows.length ? '<div class=\"tablewrap\" style=\"margin-top:12px\"><table><thead><tr><th>When</th><th>Who</th><th>Action</th><th>Player</th><th>Details</th></tr></thead><tbody>' +\n      d.rows.map(x => '<tr><td>' + when(x.ts) + '</td><td class=\"mono\">' + esc(x.who) + '</td><td><b>' + esc(x.action) + '</b></td><td>' + (x.target ? '<a href=\"#players/' + esc(x.target) + '\" class=\"mono\">' + esc(x.target) + '</a>' : '') + '</td><td class=\"mono\" style=\"max-width:420px;word-break:break-word\">' + esc(x.detail || '') + '</td></tr>').join('') +\n      '</tbody></table></div>' : '<div class=\"card empty\">Nothing yet</div>');\n};\n\n// players linked from anywhere (#players/ID) open in the drawer\nwindow.addEventListener('hashchange', () => { const p = location.hash.split('/'); if (p[0] === '#players' && p[1] && state.view !== 'players') {} });\n\napi('/overview').then(start).catch(e => { if (e.message !== 'Signed out') { $('#root').innerHTML = '<div class=\"card login\">' + (e.message === 'admin_off' ? 'The dashboard is off: set <b>ADMIN_KEY</b> on the server, then reload.' : esc(e.message)) + '</div>'; } });\n</script>\n</body>\n</html>\n";
/** The dashboard page served at /admin. */
export const dashboardPage = (): string => HTML;
